// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":32,"question":"سائل يقول: يلبس الشيطان، وقرناء السوء على بعض الشباب في مسألة القدر، وأنه لا فائدة من التمسك بالدين ما دام الأمر قد فُرغ منه، نرجو التوجيه من سماحتكم، جزاكم الله خير الجزاء؟","title":"ما الرد على شبهة جدوى العمل مع القَدَر؟","answer":"الجواب: هذه الشبهة قد وقعت قديمًا في عهد النبي ﷺ، وقعت للصحابة ، فإن الرسول ﷺ لما حدّثهم، وقال: ما منكم من أحد إلا وقد عُلِمَ مقعده من الجنة ومقعده من النار، قالوا: يا رسول الله ففيمَ العمل حينئذ؟ قال: اعملوا فكل ميسر لما خلق له؛ أما أهل السعادة فيُيَسَّروا لعمل أهل السعادة، وأما أهل الشقاوة فيُيَسَّروا لعمل أهل الشقاوة، ثم تلا قوله سبحانه: فَأَمَّا مَنْ أَعْطَى واتَّقَى  ۝  وصَدَّقَ بِالْحُسْنَى  ۝  فَسَنُيَسِّرُهُ لِلْيُسْرَى  ۝  وأَمَّا مَنْ بَخِلَ واسْتَغْنَى  ۝  وكَذَّبَ بِالْحُسْنَى  ۝  فَسَنُيَسِّرُهُ لِلْعُسْرَى [الليل:5-10] ). هذا يبين لنا أن القدر مفروغ منه، وأن الله قد علم كل شيء، وأحصى كل شيء ؛ ولكنه جعل لهذا أسبابًا، ولهذا أسبابًا، فللخير أسباب، وللشر أسباب، وللجنة أعمال، وللنار أعمال، فمن كان من أهل السعادة وفقه الله لأعمال أهل السعادة وأعانه، ومن كان من أهل الشقاوة يُيَسَّر لعمل أهل الشقاوة..... ولا حول ولا قوة إلا بالله.\nفعلى المؤمن أن يجدَّ في العمل الذي يعلم أنه طيب، وأنه من أعمال أهل السعادة، على المؤمن أن يجِدَّ فيه، وأن يسارع إليه، وأن يكثر منه، وأن يحذر من الأعمال التي جعلها الله من أعمال أهل الشقاوة، ويبتعد عنها، وينفّر الناس منها.","link":"https://binbaz.org.sa/fatwas/2812/ما-الرد-على-شبهة-جدوى-العمل-مع-القدر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0005.mp3","categories":["القضاء والقدر"]},{"id":778,"question":"هل الدعاء يردّ القدرَ؟ فقد رُوي عن عمر بن الخطاب  أنه قال: \"اللهم إن كنتَ قد كتبتني شقيًّا فامحه، واكتُبني سعيدًا، اللهم إن كنتَ قد كتبتني ميتًا فامحه، واكتبني شهيدًا\"؟","title":"هل الدعاء يَرُدّ القدر؟","answer":"الجواب: جاء في الحديث: لا يرد القدرَ إلا الدعاء، والمعنى: في القدر المُعَلَّق، فإنَّ الدعاء والقدر يتعالجان، فالمراد بالقدر: غير المحتوم الذي ليس بمعلّقٍ، فالقدر المحتوم لا حيلةَ فيه: كالموت، لو قال: \"اللهم لا تُمتني\" سيموت، ولكن القدر المعلَّق الذي قد علَّقه الله على شيءٍ، فهذا الدعاء من التَّعليق، مما قدّره الله، فقد يكون الإنسانُ كُتب عليه أنه إن لم يُسافر إلى كذا وكذا جرى عليه كذا وكذا، فيُشجعه الله ويُقدر له السَّفر، فيُسافر ويسلم مما علَّق الله جلَّ وعلا على عدم السفر؛ لأنه سبحانه هو الذي أراد السفر ودبَّره له لو علَّق ذلك على ضررٍ معينٍ: حصول مرضٍ معينٍ، أو على لقاء شخصٍ، أو ما أشبه ذلك، قدرٌ مُعلَّقٌ، فهذه الأقدار المعلَّقة إنما تتم بوجود شرائطها التي علَّقها الله عليها سبحانه وتعالى.\nوأما ما يُروى عن عمر: فهذا ليس عن عمر، إنما يُروى عن ابن عمر: أنه كان يقول: \"اللهم إن كنتَ كتبتني شقيًّا فاكتبني سعيدًا\"، فهذا من ابن عمر، يظن أنه داخلٌ في قوله تعالى: يَمْحُو اللَّهُ مَا يَشَاءُ وَيُثْبِتُ وَعِنْدَهُ أُمُّ الْكِتَابِ [الرعد:39].\nوالمعروف عند جمهور أهل العلم: أنَّ مَن كُتب شقيًّا لا يتزعزع، يكون شقيًّا، ومَن كُتب سعيدًا فهو سعيد، كما قال النبيُّ ﷺ لما سُئل عن القدر قال: ما منكم من أحدٍ إلا وقد عُرض مقعده من الجنَّة ومقعده من النار، قالوا: يا رسول الله، ففيمَ العمل؟ قال: إنَّ الله جلَّ وعلا قدَّر الأقدار، فمَن كان من أهل السَّعادة يسَّر له عمل أهل السَّعادة، ومَن كان من أهل الشَّقاوة يسَّر له عمل أهل الشَّقاوة، وقال: كلٌّ مُيَسَّرٌ لما خُلِقَ له ثم تلا قوله تعالى: فَأَمَّا مَنْ أَعْطَى وَاتَّقَى ۝ وَصَدَّقَ بِالْحُسْنَى  ۝   فَسَنُيَسِّرُهُ لِلْيُسْرَى  ۝   وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى  ۝ وَكَذَّبَ بِالْحُسْنَى  ۝   فَسَنُيَسِّرُهُ لِلْعُسْرَى [الليل:5- 10]، وإنما القدر الذي يُمْحَى هو المُعَلَّق على شيءٍ.\nوكذلك الشرائع ينسخ الله منها ما يشاء، يمحو الله ما يشاء، ويثبت من الشرائع والحسنات والسّيئات بأسبابها، أمَّا القدر المحتوم الذي كتبه الله ولم يُعلَّق فهذا لا يُغيَّر: كالسعادة، والشقاوة، والموت، ونحو ذلك.","link":"https://binbaz.org.sa/fatwas/20729/هل-الدعاء-يرد-القدر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0610هل يرد الدعاء القدر؟ ابن باز فتاوى المحاضرات.mp3","categories":["القضاء والقدر"]},{"id":938,"question":"يقول السائل أنه نُشر خبرٌ في إحدى الجرائد: أن امرأةً ولدت خمسة أولاد، وكانت تلد كل واحدٍ في نفس اليوم من العام الذي يلي الميلاد الأول، ثم ذكر الخبرُ أنَّ هذا صدفة بحتة، كاتب الخبر يقول أنَّ هذا من باب الصُّدفة المحضة، ثم قال: وقد أكَّد أنَّ الصدفة هي التي تلعب دورها في ذلك، ثم قال: وأنَّ الأمر كله كان بالصدفة البحتة؟","title":"ما حكم نسبة الأمور إلى الصُّدْفة ونحوها؟","answer":"الجواب: كل هذا باطل، ما هي بالصُّدَف، بل بتقدير الله ربنا، يعلم ما يشاء، وَمَا تَحْمِلُ مِنْ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلْمِهِ ، هو علَّام الغيوب: اللَّهُ يَعْلَمُ مَا تَحْمِلُ كُلُّ أُنْثَى وَمَا تَغِيضُ الْأَرْحَامُ وَمَا تَزْدَادُ وَكُلُّ شَيْءٍ عِنْدَهُ بِمِقْدَارٍ [الرعد:8] ، فالتي ولدت في كل عام بأيامٍ معلومةٍ، أو في يوم معلومٍ صادف في يومٍ رابع الشهر، أو في عاشر الشهر، ليس هذا مجرد صدفةٍ، بل بقدر، بعلم من الله وتقديره . ولكن هذا جاهلٌ مُرَكَّب، لا يؤمن بقدر الله، فوَضْعُ الحمل وتعلُّقه بالرحم كله بقدر الله، تخطيطه جميل أو دميم، تامٌّ أو ناقصٌ، كله بتقدير الله ، لا بمجرد الصدفة، بل بقدرٍ سابقٍ قدَّره الله، يُولَد في كذا، أو يموت في كذا، أو يتخلَّق في كذا، أو يضمه الرحم في كذا، إلى غير ذلك، كله بقدرٍ معلومٍ.\nولهذا يقول ﷺ: كل شيءٍ بقدرٍ، حتى العجز والكيس، إِنَّا كُلَّ شَيْءٍ خَلَقْنَاهُ بِقَدَرٍ [القمر:49]، هكذا يقول .\nس: كان إذا تقابل بعضُ الناس مع البعض بدون ميعادٍ يقولون: هذا من باب الصّدفة أو صدفةً؟\nالشيخ: يعني: هذا بالنسبة إليهم هم، ما هو بالنسبة إلى الله، يعني: أنهم ما تواعدوا، هذا معناها، يعني: إذا لقيته في الطريق أو في محلِّ فلانٍ تقول: صدفة، يعني: ما واعدته، لقيتُه عن غير ميعادٍ، يُسمونه: صدفة، اصطلاحًا بينهم، اصطلاحًا بين الناس، لا حرج فيه ما بين الناس، لكن بالنسبة إلى الله لا، عن علمٍ، عن قدرٍ سابقٍ.","link":"https://binbaz.org.sa/fatwas/20975/ما-حكم-نسبة-الامور-الى-الصدفة-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0771ما حكم قول أن بعض الأمور تكون بالصدفة البحتة؟ ابن باز فتاوى المحاضرات.mp3","categories":["القضاء والقدر"]},{"id":990,"question":"إني أُحبُّكم في الله، ثم ما رأي فضيلتكم في عقيدة أهل السنة والجماعة في القدر؟ وهل الإنسانُ مُخيَّرٌ أم مُسَيَّرٌ؟ أفتونا مأجورين.","title":"ما عقيدة أهل السنة والجماعة في القدر؟","answer":"الجواب: أما حبُّك في الله: والله جلَّ وعلا يُجازيك عنه خيرًا، ونقول: أحبَّك الله الذي أحببتنا له، وقد تقدَّم الكلامُ في ذلك، وأن الحبَّ في الله والبغضَ في الله أوثقُ عُرى الإيمان، والرسول عليه السلام قال: لا يؤمن أحدُكم حتى يُحبَّ لأخيه ما يُحبُّ لنفسه، وقال عليه الصلاة والسلام: ثلاثٌ مَن كنَّ فيه وجد حلاوةَ الإيمان: أن يكون الله ورسوله أحبَّ إليه مما سواهما، وأن يُحبَّ المرء لا يُحبُّه إلا لله، وأن يكره أن يعود في الكفر بعد إذ أنقذه الله منه، كما يكره أن يُقذف في النار.\nوأما ما يتعلق بالقدر: فقد تقدَّم في المحاضرة التي مضت في الأسبوع الماضي في الحرس بيان مراتب القدر، وأهل السنة والجماعة يُؤمنون بالقدر، وأنه حقٌّ، وأن العباد يمضون في قدر الله، فقد ثبت عنه ﷺ أنهم سألوه -سأله الصحابة- قالوا: يا رسول الله، أرأيتَ ما نعمل فيه ونكدح: هل هو في أمرٍ مضى قد فُرغ منه وكُتب أم في أمرٍ مُستأنفٍ؟ قال: بل في أمرٍ قد مضى وفُرغ منه، قالوا: يا رسول الله، ففيمَ العمل؟ قال: اعملوا فكلٌّ مُيَسَّرٌ لما خُلِقَ له: أما أهل السَّعادة فيُيَسَّرون لعمل أهل السَّعادة، وأما أهل الشَّقاوة فيُيَسَّرون لعمل أهل الشَّقاوة، ثم تلا قوله تعالى: فَأَمَّا مَنْ أَعْطَى وَاتَّقَى  ۝  وَصَدَّقَ بِالْحُسْنَى  ۝  فَسَنُيَسِّرُهُ لِلْيُسْرَى  ۝  وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى  ۝  وَكَذَّبَ بِالْحُسْنَى  ۝  فَسَنُيَسِّرُهُ لِلْعُسْرَى [الليل:5- 10].\nفالإيمان بالقدر على مراتب أربع، مَن جمعها جمع الإيمانَ بالقدر:\nالأول: الإيمان بعلم الله بالأشياء، وأنه يعلم كلَّ شيءٍ من أعمالنا وآجالنا وأرزاقنا وغير ذلك.\nالمرتبة الثانية: الكتابة، وأنه كتب ذلك سبحانه وتعالى عنده، كما قال تعالى: أَلَمْ تَعْلَمْ أَنَّ اللَّهَ يَعْلَمُ مَا فِي السَّمَاءِ وَالْأَرْضِ إِنَّ ذَلِكَ فِي كِتَابٍ [الحج:70]، وقال: إِنَّ اللَّهَ بِكُلِّ شَيْءٍ عَلِيمٌ [الأنفال:75]، وقال : لِتَعْلَمُوا أَنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ وَأَنَّ اللَّهَ قَدْ أَحَاطَ بِكُلِّ شَيْءٍ عِلْمًا [الطلاق:12].\nالثالث: أنَّ ما شاء الله كان، وما لم يشأ لم يكن، فلا يقع في ملكه ما لا يُريد، قال تعالى: وَلَوْ شَاءَ رَبُّكَ مَا فَعَلُوهُ [الأنعام:112]، وقال: لِمَنْ شَاءَ مِنْكُمْ أَنْ يَسْتَقِيمَ  ۝  وَمَا تَشَاءُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ رَبُّ الْعَالَمِينَ [التكوير:28- 29]، وقال سبحانه: فَمَنْ شَاءَ ذَكَرَهُ  ۝  وَمَا يَذْكُرُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ [المدثر:55- 56]، فلا بدّ من الإيمان بمشيئة الله، وأنه لا يقع شيءٌ في ملك الله بدون مشيئته ، فأعمالنا وسائر حركاتنا وسكناتنا كلها بمشيئة الله ، ولا نشاء شيئًا إلا بعد مشيئته جلَّ وعلا.\nالرابعة: الإيمان بأنه خالقُ الأشياء ومُقدِّرها، الله خالق كل شيءٍ ، قال تعالى: مَا أَصَابَ مِنْ مُصِيبَةٍ فِي الْأَرْضِ وَلَا فِي أَنْفُسِكُمْ إِلَّا فِي كِتَابٍ مِنْ قَبْلِ أَنْ نَبْرَأَهَا [الحديد:22].\nهذه مراتب القدر: العلم، والكتابة، والإيمان بأن ما شاء الله كان، وما لم يشأ لم يكن، والإيمان بأنه خالق الأشياء، ومُوجِدها، هذه أربع مراتب نبَّه عليها شيخُ الإسلام ابن تيمية في \"الواسطية\"، ونبَّه عليها العلماء في كُتبهم، ونبَّه عليها العلامةُ ابن القيم في كتابه \"شفاء العليل\".\nفالإنسان مُخيَّرٌ ومُسَيَّرٌ، أعطاه الله عقلًا، وأعطاه الله إرادةً، وأعطاه مشيئةً، فهو مُخيَّرٌ من هذه الحيثية، يعمل عن مشيئةٍ، وعن إرادةٍ، كما قال تعالى: تُرِيدُونَ عَرَضَ الدُّنْيَا وَاللَّهُ يُرِيدُ الْآخِرَةَ [الأنفال:67]، وقال: لِمَنْ شَاءَ مِنْكُمْ أَنْ يَسْتَقِيمَ  ۝  وَمَا تَشَاءُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ، وقال: إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ [النور:30]، خَبِيرٌ بِمَا تَعْمَلُونَ [آل عمران:153]، بِمَا يَفْعَلُونَ [يونس:36]، فلهم فعلٌ، ولهم مشيئةٌ، ولهم اختيارٌ، ولكن لا يشاؤون إلا ما شاءه الله، كما قال تعالى: وَمَا تَشَاءُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ [التكوير:29]، هُوَ الَّذِي يُسَيِّرُكُمْ فِي الْبَرِّ وَالْبَحْرِ [يونس:22].\nفهو مخيَّرٌ من جهة أنَّ له إرادةً، وله مشيئةً، وله اختيارًا، يعرف الضَّارَّ من النافع، والطيبَ من الخبيث، يأكل ويشرب باختياره، يزور إخوانه باختياره، ينام باختياره، يقوم باختياره، له اختيار، يأتي الطاعة باختياره، ويأتي المعصية باختياره، لكن هذا له مشيئة سابقة، وله قدر من الله سابق ، لا يخرج عن ملك الله، ولا عن إرادته جلَّ وعلا: إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَنْ يَقُولَ لَهُ كُنْ فَيَكُونُ [يس:82] .\nفهو مُخيَّرٌ من جهة ما أعطاه الله من المشيئة والقُدرة والاختيار والفهم، ومُسَيَّرٌ من جهة أنه لا يخرج عن قدر الله.","link":"https://binbaz.org.sa/fatwas/21018/ما-عقيدة-اهل-السنة-والجماعة-في-القدر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0815ما عقيدة أهل السنة والجماعة في القدر وهل الإنسان مخير أم مسير؟ ابن باز فتاوى المحاضرات.mp3","categories":["القضاء والقدر"]},{"id":1255,"question":"يقول السائل: إنَّ بعض العوام يتساءلون عن بعض الأشياء، منها يقولون: كيف أن علم الله  سبق بما هو كائنٌ إلى يوم القيامة؟ وكيف أن الإنسان بعد ذلك مُخيَّر في هذه الدنيا إلى سبيل الإيمان أو سبيل الكفر؟ ولم يستطع هؤلاء التوفيق بين هذين الأمرين، نرجو من سماحتكم أن تكشفوا هذه الغُمَّة؟","title":"كيف يكون الإنسان مُخَيَّرًا مع علم الله السابق؟","answer":"الجواب:\nعلم الله سابقٌ، قد قدَّر المقادير كلها سبحانه وتعالى، وعلم أهل الجنة وأهل النار، في الحديث الصحيح من حديث عبدالله بن عمرو عند مسلم: إنَّ الله قدَّر مقادير الخلائق قبل أن يخلق السَّماوات والأرض بخمسين ألف سنة، وعرشه على الماء، ثم كتب في الذكر كلَّ شيءٍ، وفي الأحاديث الصحيحة أنه قال للصحابة: ما منكم من أحدٍ إلا وقد علم مقعدَه من الجنة، ومقعده من النار، فقيل: يا رسول الله، ففيم العمل؟ قال: اعملوا، فكلٌّ مُيَسَّرٌ لما خُلِقَ له، أما أهل السعادة فيُيسرون لعمل أهل السعادة، وأما أهل الشَّقاوة فيُيسرون لعمل أهل الشقاوة، ثم تلا قوله : فَأَمَّا مَنْ أَعْطَى وَاتَّقَى  ۝  وَصَدَّقَ بِالْحُسْنَى  ۝ فَسَنُيَسِّرُهُ لِلْيُسْرَى  ۝  وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى  ۝  وَكَذَّبَ بِالْحُسْنَى  ۝  فَسَنُيَسِّرُهُ لِلْعُسْرَى [الليل:5- 10]، وهذا في \"الصحيحين\" من حديث عليٍّ .\nفالمقصود أن مقادير الخلائق معلومة، قد سبق في علم الله ما يقع من المخلوقين، ولكنه سبحانه لا يُعذِّبهم بعلمه فيهم، بل أعطاهم العقول، وأعطاهم الإمكانات: السمع والبصر واليد والرِّجْل، وأرسل الرسل، وأنزل الكتب، وأمرهم ونهاهم، كما قال تعالى: وَاللَّهُ أَخْرَجَكُمْ مِنْ بُطُونِ أُمَّهَاتِكُمْ لَا تَعْلَمُونَ شَيْئًا وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ لَعَلَّكُمْ تَشْكُرُونَ [النحل:78]، وقال: آمِنُوا بِاللَّهِ وَرَسُولِهِ وَأَنْفِقُوا [الحديد:7]، وقال: يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ [النساء:1]، فهم مأمورون منهيُّون، ولهم عقول يعرفون الشرَّ من الخير، لو أردتَ أن تأخذ منه ريالًا ما أعطاك إلا بهواه، كذلك لو أردتَ أن تمنعه من حاجةٍ ما أطاع إلا بهواه، وإلا قاتلك، وإلا ضاربك، وإلا صار بينك وبينه مشكل، ما يحتجّ بالقدر، لو قلتَ له: أعطنا هذه العباءة التي عليها البشت هو مقدَّرٌ لي، ما أطاع، لا يُعطيك العباءة، ولا يُعطيك غيرها ولو احتججتَ بالقدر، فكيف يحتج بالقدر وهو لا يعمل بالقدر؟!\nالقدر علمه عند الله جلَّ وعلا، فلا يجوز للإنسان أن يحتجَّ بالقدر إلا في المصائب، إذا نزلت المصيبة يقول: إنا لله وإنا إليه راجعون، عند المصيبة يحتجُّ بالقدر: قدر الله وما شاء فعل، وأما عند أعماله ومعاصيه وأعمال الناس لا، لا يحتج بالقدر، عليه أن يعمل ويكدح ويتَّقي الله، لو أنَّ إنسانًا ضربه أو أخذ ماله وقال: هذا مُقدَّر، ما أطاع، طالبه بحقِّه في ضربه، وحقِّه في أخذ ماله، ما أطاع في الاحتجاج بالقدر، ومعلومٌ أنه ما ضربك ولا أخذ مالك إلا بقدرٍ، وأنت ما ترضى بهذا، تطلب حقَّك، فإذا كنتَ لا ترضى بهذا في حقِّك وتُطالب، فهكذا مسألة المعصية، إذا عصيتَ: من شرب الخمر، وترك الصلاة، وفي الزنا، فأنت محجوجٌ؛ لأنَّك قد علمتَ، وجُعل لك اختيارٌ، وجُعلت لك بصيرةٌ؛ فعليك أن تمتنع عن الباطل، وعليك أن تقدم على الحقِّ.","link":"https://binbaz.org.sa/fatwas/21319/كيف-يكون-الانسان-مخيرا-مع-علم-الله-السابق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1062هل الإنسان مخير؟ ابن باز فتاوى.mp3","categories":["القضاء والقدر"]},{"id":3003,"question":"توضيح مسألة ارتباط القدر بالدعاء؟","title":"ما معنى \"لا يَرُدُّ القدرَ إلا الدعاءُ\"؟","answer":"الجواب: لا يَرُدُّ القدرَ إلا الدعاءُ معناه: أن الله جل وعلا كتب كل شيء، وقد يُعَلّق بعضَ الأشياء بأفعال العبد، يكون هذا مُقَدّرًا زواجه، مُقَدّر بدعوته زواجه، مُقَدّر بعمله الصالح الفلاني حجه صلاته صدقاته. الأقدار قسمان: قسم مُبْتُوت فيه، ما هو مُعَلّق بشيء مثل الموت وأشباهه، هذا لا حيلة فيه.  وقسم مُعَلّق: فلان يطول عمره؛ لأنه سوف يصل رحمه، قد كتب الله هذا، فهو يُوفّق يُيَسّر لما خُلق له من صلة الرحم ومن الصدقات التي هي أسباب طول عمره وهدايته. كما قال ﷺ: اعملوا فكل مُيَسّر لما خُلق له، أما أهل السعادة فيُيَسرون لعمل أهل السعادة، وأما أهل الشقاء فيُيَسرون لعمل أهل الشقاء، أشياء مربوطة بأقدارها.","link":"https://binbaz.org.sa/fatwas/23161/ما-معنى-لا-يرد-القدر-الا-الدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/توضيح مسألة ارتباط القدر بالدعاء.mp3","categories":["الأدعية والأذكار","القضاء والقدر"]},{"id":4325,"question":"الدعاء هل يرد القدر؟","title":"ما القَدَرُ الذي يرده الدعاء؟","answer":"الجواب: القدر المعلَّق، المعلَّق بالدعاء، القدر المعلَّق له أسباب إذا وقعت عافى الله العبد منه.","link":"https://binbaz.org.sa/fatwas/24600/ما-القدر-الذي-يرده-الدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الدعاء يرد القدر.mp3","categories":["الأدعية والأذكار","القضاء والقدر"]},{"id":4735,"question":"الله  أراد من أبي لهب الإيمانَ كونًا أو شرعًا؟","title":"هل أراد الله الإيمانَ من أبي لهب كونًا أو شرعًا؟","answer":"شرعًا، ولو أراده كونًا لوقع، لكن ما أراده كونًا، أراده شرعًا من جميع الناس، لكن مَن أراده كونًا منهم وقع، فأبو طالب وأبو لهب أُريد منهم الإسلام شرعًا فلم يتقبَّلا، وأما الإرادة الكونية فقد مضى في علم الله أنهما لا يُسلمان.","link":"https://binbaz.org.sa/fatwas/25047/هل-اراد-الله-الايمان-من-ابي-لهب-كونا-او-شرعا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل أراد الله من أبي لهب الإيمانَ كونًا أو شرعًا.mp3","categories":["القضاء والقدر"]},{"id":4740,"question":"ما الفرق بين الإرادة والمشيئة؟","title":"ما معنى الإرادة والمشيئة؟ وما الفرق بينهما؟","answer":"الإرادة إرادتان: شرعية وقدرية، فالإرادة الشرعية تُوافق الأمر والرضى والمحبَّة، مثل قوله: يُرِيدُ اللَّهُ لِيُبَيِّنَ لَكُمْ وَيَهْدِيَكُمْ سُنَنَ الَّذِينَ مِنْ قَبْلِكُمْ [النساء:26]، وقال جلَّ وعلا: إِنَّمَا يُرِيدُ اللَّهُ لِيُذْهِبَ عَنْكُمُ الرِّجْسَ أَهْلَ الْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا [الأحزاب:33]، هذه إرادة شرعية بمعنى الأمر، وبمعنى الرضا.\nوالإرادة الكونية بمعنى المشيئة، كما قال سبحانه: إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَنْ يَقُولَ لَهُ كُنْ فَيَكُونُ [يس:82]، هذه معناها المشيئة، فَمَنْ يُرِدِ اللَّهُ أَنْ يَهْدِيَهُ يَشْرَحْ صَدْرَهُ لِلْإِسْلَامِ وَمَنْ يُرِدْ أَنْ يُضِلَّهُ يَجْعَلْ صَدْرَهُ ضَيِّقًا حَرَجًا [الأنعام:125]، هذه الإرادة الكونية وأشباهها كثير، غالب الإرادات في القرآن كونية.\nوبعضهم جعل المشيئةَ قسمين مثل الإرادة، وبعضهم اقتصر بهذا على الإرادة فقط، أما المشيئة فلا تكون إلا كونية: ما شاء الله كان، وما لم يشأ لم يكن، ولكن لو ورد الاثنان أحيانًا بمعنى الإرادة الشرعية فلا مانع، الإرادة الشرعية والمشيئة الشرعية معناهما واحد، فإنه يقال: إنه سبحانه شاء شرعًا، وأراد شرعًا من العباد أن يعبدوه، وأن يُطيعوه، ولكنه أراد وشاء كونًا من الكافر أن يكفر، ومن العاصي أن يعصي؛ لحكمةٍ بالغةٍ.","link":"https://binbaz.org.sa/fatwas/25068/ما-معنى-الارادة-والمشيىة-وما-الفرق-بينهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الفرق بين الإرادة والمشيئة.mp3","categories":["القضاء والقدر"]},{"id":5086,"question":"سائل يقول: يلبِّس الشيطان وقرناء السوء على بعض الشباب في مسألة القدر، وأنه لا فائدة من التمسك بالدين ما دام الأمر قد فُرغ منه، نرجو التوجيه من سماحتكم، جزاكم الله خير الجزاء؟","title":"ما الرد على شبهة ترك العمل لأن القدر فُرغ منه؟","answer":"الجواب: هذه الشبهة قد وقعت قديمًا في عهد النبي ﷺ، وقعت للصحابة ، فإن الرسول ﷺ لما حدثهم، وقال: ما منكم من أحد إلا وقد عُلِمَ مقعده من الجنة ومقعده من النار، قالوا: يا رسول الله! ففيمَ العمل حينئذ؟! قال: اعملوا فكل ميسر لما خلق له؛ أما أهل السعادة فيُيَسَّروا لعمل أهل السعادة، وأما أهل الشقاوة فيُيَسَّروا لعمل أهل الشقاوة، ثم تلا قوله سبحانه: فَأَمَّا مَنْ أَعْطَى واتَّقَى  ۝  وصَدَّقَ بِالْحُسْنَى  ۝  فَسَنُيَسِّرُهُ لِلْيُسْرَى  ۝  وأَمَّا مَنْ بَخِلَ واسْتَغْنَى  ۝  وكَذَّبَ بِالْحُسْنَى  ۝  فَسَنُيَسِّرُهُ لِلْعُسْرَى [الليل:5-10]. هذا يبين لنا أن القدر مفروغ منه، وأن الله قد علم كل شيء، وأحصى كل شيء ؛ ولكنه جعل لهذا أسبابًا، ولهذا أسبابًا، فللخير أسباب، وللشر أسباب، وللجنة أعمال، وللنار أعمال، فمن كان من أهل السعادة وفقه الله لأعمال أهل السعادة وأعانه، ومن كان من أهل الشقاوة يُيَسَّر لعمل أهل الشقاوة... ولا حول ولا قوة إلا بالله. فعلى المؤمن أن يجدَّ في العمل الذي يعلم أنه طيب، وأنه من أعمال أهل السعادة، على المؤمن أن يجِدَّ فيه، وأن يسارع إليه، وأن يكثر منه، وأن يحذر من الأعمال التي جعلها الله من أعمال أهل الشقاوة، ويبتعد عنها، وينفر الناس منها.","link":"https://binbaz.org.sa/fatwas/29988/ما-الرد-على-شبهة-ترك-العمل-لان-القدر-فرغ-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 05.mp3","categories":["القضاء والقدر"]},{"id":5364,"question":"الاحتجاج بالقدر قبل التوبة من المعصية؟","title":"حكم الاحتجاج بالقدر قبل التوبة من المعصية","answer":"الجواب: قبل التوبة ما يجوز، لا يجوز لأحدٍ أن يحتجَّ بالقدر. س: وبعد التَّوبة؟ ج: بعد التوبة لا حرج، مثلما فعل آدم. س: يصح احتجاجه بالمصائب لا بالمعائب؟ ج: نعم، وكذلك من الجواب: أنه لامه على المصيبة.[1]","link":"https://binbaz.org.sa/fatwas/31073/حكم-الاحتجاج-بالقدر-قبل-التوبة-من-المعصية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/tawheed_ibnkhozaima007.mp3","categories":["القضاء والقدر"]},{"id":5701,"question":"هل صح ما قيل أن الدعاء يغير القدر، أو القضاء؟ أي أنه عندما يوجد الطفل يكتب الملك له في الكتاب أشقي هو أم سعيد، هل إذا كان شقيًّا يغير الدعاء الشقاء إلى سعادة؟","title":"هل الدعاء يرد القضاء؟","answer":"الجواب:  ظاهر النصوص أن الشقاوة والسعادة أمر محكم من الله  ليس فيه تغيير، والآجال: أجل الموت، والأرزاق، ونحو ذلك كلها محكمة، ولكن هناك قدر معلق على أشياء يفعلها العبد، سبق في علم الله أنه يفعلها. فالقدر المعلق على شيء، على بر والديه، وعلى صلة رحمه، أو على فعله كذا يوجد عند وجود الفعل من الشخص، فهناك أقدار معلقة على أشياء يفعلها الإنسان، فالله يعلم كل شيء  لا تخفى عليه خافية، قد جعل البر من أسباب زيادة العمر، وصلة الرحم، كذلك وجعل المعاصي والسيئات من أسباب نزع البركة، ومن أسباب قصر الأعمار إلى غير ذلك. فالحاصل: أن هناك أقدار معلقة توجد بأسبابها، ومعلقة عليها، وهناك أقدار محكمة ليس فيها تغيير، لا تغير بالدعاء، ولا بغير الدعاء، كالشقاوة، والسعادة، والآجال المضروبة، والمحكمة، إلى غير ذلك. وذهب بعض أهل العلم إلى أن كل شيء يمكن تغييره؛ لأن الله قال: يَمْحُو اللّهُ مَا يَشَاءُ وَيُثْبِتُ وَعِندَهُ أُمُّ الْكِتَابِ [الرعد: 39] وأن الله -جل وعلا- أمر بالدعاء، وشرع الأسباب، وعلق ما يشاء على ما يشاء  علق الشقاوة على شيء، والسعادة على شيء، وهو حكيم عليم يعلم ما يصير إليه أمر العبد. فإذا اجتهد في طاعة الله، وسأل ربه ... من الشقاوة إلى السعادة أن هذا قد يقع، ويكون القدر ليس محتمًا، بل معلق، فيروى عن بعض السلف، وعن عمر أيضًا أنه كان يقول: \"اللهم إن كنت كتبتني شقيًّا، فاكتبني سعيدًا\" هذا قاله جماعة من أهل العلم.  والمشهور عند أهل العلم، والأكثرين: الأول، وأن الشقاوة والسعادة والآجال مفروغ منها، وهذا يدل عليه الحديث الصحيح حديث علي -رضي الله عنه وأرضاه- أنهم سألوا  الصحابة، قالوا: يا رسول الله  هذا الذي نعمل أهو في أمر قد مضى، وفرغ منه، أو في أمر مستقبل؟ قال: بل في أمر قد فرغ، ومضى وفرغ منه قالوا: يا رسول الله، ففيم العمل؟ قال: اعملوا فكل ميسر لما خلق له، أما أهل السعادة فييسرون لعمل أهل السعادة، وأما أهل الشقاوة فييسرون لعمل أهل الشقاوة ثم قرأ النبي ﷺ: فَأَمَّا مَن أَعْطَى وَاتَّقَى  ۝  وَصَدَّقَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْيُسْرَى ۝ وَأَمَّا مَن بَخِلَ وَاسْتَغْنَى ۝ وَكَذَّبَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْعُسْرَى[الليل:5-10]. والصواب: هو قول الأكثرين، وأن الأشياء المقدرة مضى بها علم الله، وفرغ منها علم الله  هذه لا تغير؛ ولكن الله -جل وعلا- يوفق العباد لأسباب توصلهم إلى ما قدر لهم، توصل السعيد إلى السعادة، وتوصل الشقي إلى الشقاوة، ولا حول ولا قوة إلا بالله، كل ميسر لما خلق له. السؤال: الدعاء هذا عن عمر، أم عن ولده؟ الجواب: الذي أذكره أنه يروى عن عمر\n\nالسؤال: الحديث الذي ورد عن النبي -عليه الصلاة والسلام- (اللهم يا مقلب القلوب) ..... وأن قلوب العباد بين أصبعين من أصابع الرحمن؟ الجواب: هذا ما ينافي... ما سبق به علمه سبحانه، هو مقلب القلوب على ما سبق به علمه. السؤال: يا شيخ ما في حديث يقول: أن البلاء والدعاء يتعالجان بين السماء والأرض؟ الجواب: بلى السؤال: صحيح هذا الحديث؟ الجواب: جيد نعم، لكن لا ينافي ما سبق به علم الله، كل يوفق لما قدر له.","link":"https://binbaz.org.sa/fatwas/997/هل-الدعاء-يرد-القضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_26.mp3","categories":["الأدعية والأذكار","القضاء والقدر"]},{"id":6962,"question":"آمل إيضاح هذه النقطة التي يحتج بها العامة يقول: إنه إذا كانت السيئات، والمعاصي مكتوبة على الإنسان من عند الله -سبحانه- دون ذنب من الإنسان، فلماذا يحاسب الإنسان على ذلك بالعذاب في الآخرة، نرجو إيضاح ذلك؟","title":"الرد على الجبرية بأن المعاصي مكتوبة على العباد","answer":"الجواب:\n\nهذا المكتوب سبق في علم الله، ولها أسباب، سبق علم الله أن هذا يعمل كذا، ويعمل كذا، ويعمل كذا، وهذا يعمل كذا وكذا، مثل ما قال تعالى: فَلَمَّا زَاغُوا أَزَاغَ اللَّهُ قُلُوبَهُمْ [الصف:5] وَنُقَلِّبُ أَفْئِدَتَهُمْ وَأَبْصَارَهُمْ كَمَا لَمْ يُؤْمِنُوا بِهِ أَوَّلَ مَرَّةٍ وَنَذَرُهُمْ فِي طُغْيَانِهِمْ يَعْمَهُونَ [الأنعام:110].\n\nفما قدر الله عليهم له أسباب منهم: وهو غفلتهم، وإعراضهم، وعدم إجابتهم المنادي، والداعي إلى الله  وعدم انشراح صدورهم لهذا الأمر.\n\nفالله -جل وعلا- قضى ما قضى، وقد قدر ما قدر من السيئات، والحسنات لما سبق في علمه من أن هؤلاء يجيبون إلى الخير، ويطلبونه، ويريدونه، وتنشرح صدورهم له بتوفيقهم له . \n\nوأولئك لا تنشرح صدورهم له، ولا يطلبونه، ولا يريدونه لما حصل في قلوبهم من الكراهة له، ثم على إثر ذلك ينقادون للشيطان، ودعوة الشيطان، ودعوة النفس الأمارة بالسوء، فهذا عدله في هؤلاء، وهذا فضله في هؤلاء، فضله على من هداهم ووفقهم والله  ذو الفضل العظيم، وعدله في أولئك لما أعرضوا، ولما استكبروا عن اتباع الحق؛ صار عملهم فيما يغضب الله ويسبب هلاكهم ودمارهم -نسأل الله العافية-.","link":"https://binbaz.org.sa/fatwas/2917/الرد-على-الجبرية-بان-المعاصي-مكتوبة-على-العباد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1365.mp3","categories":["القضاء والقدر"]},{"id":6982,"question":"آمل إيضاح هذه النقطة التي يحتج بها العامة يقول: إنه إذا كانت السيئات، والمعاصي مكتوبة على الإنسان من عند الله -سبحانه- دون ذنب من الإنسان، فلماذا يحاسب الإنسان على ذلك بالعذاب في الآخرة، نرجو إيضاح ذلك؟","title":"الرد على الجبرية بأن المعاصي مكتوبة على العباد","answer":"الجواب:\n\nهذا المكتوب سبق في علم الله، ولها أسباب، سبق علم الله أن هذا يعمل كذا، ويعمل كذا، ويعمل كذا، وهذا يعمل كذا وكذا، مثل ما قال تعالى: فَلَمَّا زَاغُوا أَزَاغَ اللَّهُ قُلُوبَهُمْ [الصف:5] وَنُقَلِّبُ أَفْئِدَتَهُمْ وَأَبْصَارَهُمْ كَمَا لَمْ يُؤْمِنُوا بِهِ أَوَّلَ مَرَّةٍ وَنَذَرُهُمْ فِي طُغْيَانِهِمْ يَعْمَهُونَ [الأنعام:110].\n\nفما قدر الله عليهم له أسباب منهم: وهو غفلتهم، وإعراضهم، وعدم إجابتهم المنادي، والداعي إلى الله  وعدم انشراح صدورهم لهذا الأمر.\n\nفالله -جل وعلا- قضى ما قضى، وقد قدر ما قدر من السيئات، والحسنات لما سبق في علمه من أن هؤلاء يجيبون إلى الخير، ويطلبونه، ويريدونه، وتنشرح صدورهم له بتوفيقهم له . \n\nوأولئك لا تنشرح صدورهم له، ولا يطلبونه، ولا يريدونه لما حصل في قلوبهم من الكراهة له، ثم على إثر ذلك ينقادون للشيطان، ودعوة الشيطان، ودعوة النفس الأمارة بالسوء، فهذا عدله في هؤلاء، وهذا فضله في هؤلاء، فضله على من هداهم ووفقهم والله  ذو الفضل العظيم، وعدله في أولئك لما أعرضوا، ولما استكبروا عن اتباع الحق؛ صار عملهم فيما يغضب الله ويسبب هلاكهم ودمارهم -نسأل الله العافية-.","link":"https://binbaz.org.sa/fatwas/2917/الرد-على-الجبرية-بان-المعاصي-مكتوبة-على-العباد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1365.mp3","categories":["القضاء والقدر"]},{"id":6991,"question":"قيل: إن الدعاء والقضاء يتصارعان، وأن الدعاء قد يرد بعض القضاء، أو البلاء، كما أن الإحسان إلى الوالدين يبارك للعبد في عمره، نرجو إيضاح الضابط؟","title":"هل الدعاء يرد القضاء؟","answer":"الجواب: جاء في حديث ثوبان، عن النبي ﷺ أنه قال: إن العبد ليحرم الرزق بالذنب يصيبه، وإن القضاء لا يرده إلا الدعاء، وإن الدعاء مع القضاء يعتلجان إلى يوم القيامة، وإن البر يزيد في العمر -يعني بر الوالدين- فالدعاء قضاء، والقضاء المحتوم كذلك، فالله قد يقدر أشياء، ويدفعها بأشياء، يقدر أشياء ويدفعها بالدعاء، وبالصدقات، وبالأعمال الصالحات، ويجعل هذا دافعًا لها بقدرته .  فالقدر يعالج بالقدر، القضاء، والدعاء يعتلجان، مثل ما أنك في رعي الغنم، أو الإبل قد ترعيها أرضًا طيبة -وهذا بقدر الله- وتكون محسنًا، وقد ترعيها أرضًا رديئة، مجدبة -وهو بقدر الله- وتكون مسيئًا في عملك، فالواجب عليك أن تتحرى الطيب، وأن تبتعد عن الردئ، وكله بقدر. مثلما قال عمر للناس لما نزل الطاعون بالشام، والمسلمون هناك، وعزم عمر على الرجوع بالناس، وعدم دخول الشام -لما وقع فيها الطاعون- قال بعض الناس: \"أفِرارًا من قدر الله؟\" قال: \"نفر من قدر الله إلى قدر الله\" يعني بقاؤنا في الشام قدر، ورجوعنا قدر، كله بقدر الله، فنفر من قدر الله إلى قدر الله، وكما تفر أنت من السيئة إلى التوبة إلى الله  تفر من المرض إلى العلاج بأخذ الإبر، أو الحبوب، أو غير هذا من الأدوية، كله فرارًا من قدر الله إلى قدر الله.  ثم ضرب عمر مثلًا للناس، فقال: أرأيتم لو كان إنسان عنده إبل، أو غنم، فأراعها في روضة مخصبة، أليس بقدر الله؟ وهو بهذا مشكور، فإن رعاها، أو ذهب بها إلى أرض مجدبة، مقحطة، أو أرض خالية من الماء، والعشب؛ لكان مسيئًا -وهو بقدر الله. فالحاصل: أن الإنسان يتبع ما فيه الحق، وهو بقدر، ويدع ما فيه الباطل، وهو بقدر، كله بقدر الله، نفر من قدر الله إلى قدر الله، ولو أن إنسانًا عصى، فقد وقع على المعصية، وما يقام عليه من الحد الذي شرعه الله، هو أيضًا بقدر، فإقامة الحدود بقدر، وما وقع فيه من المعاصي بقدر، وكسبه الحلال بقدر، وكسبه الحرام بقدر، لكنه مأمور بكسب الحلال، منهي عن كسب الحرام، وكلها بأقدار الله كلها. ولا يخرج الإنسان عن قدر الله، لكنه مأمور بالتحري، مأمور بطلب الخير، والبعد عن الشر، والله جعل له عقلًا، جعل له اختيارًا يميز به بين هذا، وهذا، فيلام إذا مال إلى السيئات، إلى المعصية، إلى المسكر إلى الزنا، إلى غير ذلك، ويشكر إذا مال إلى الطاعة، وأخذ بالطاعة، واستقام على الطاعة؛ لأنه له عقل، وله إرادة، وله اختيار، وله تمييز يمييز به بين الخير، والشر، والنافع والضار، والحق، والباطل، هكذا جاءت الشريعة، وهكذا قضى الله  وقدر لعباده -جل وعلا- وأعطاهم العقول المميزة التي يميزون بها بين الحق، والباطل، والهدى، والرشاد، والغي، والرشاد، إلى غير ذلك.","link":"https://binbaz.org.sa/fatwas/2918/هل-الدعاء-يرد-القضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1366.mp3","categories":["القضاء والقدر"]},{"id":7187,"question":"ما الفرق بين الأمر القدري الشرعي، وبين الإرادة والمشيئة الشرعية القدرية؟","title":"الفرق بين الإرادة الكونية القدرية والإرادة الدينية الشرعية","answer":"الجواب:\n\nالفرق بينهما أنهما يجتمعان في حق المطيع، ويفترقان في حق العاصي والكافر، فالله سبحانه له إرادتان: قدرية وشرعية، قدرية سبق بها علمه، ومرادها نافذ، كما قوله سبحانه: إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَنْ يَقُولَ لَهُ كُنْ فَيَكُونُ [يس:82] القدرية نافذة، قال تعالى: فَمَنْ يُرِدِ اللَّهُ أَنْ يَهْدِيَهُ يَشْرَحْ صَدْرَهُ لِلْإِسْلَامِ وَمَنْ يُرِدْ أَنْ يُضِلَّهُ يَجْعَلْ صَدْرَهُ ضَيِّقًا حَرَجًا كَأَنَّمَا يَصَّعَّدُ فِي السَّمَاءِ [الأنعام:125].\n\nوهنالك إرادة شرعية كما قال -جل وعلا-: يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلَا يُرِيدُ بِكُمُ الْعُسْرَ [البقرة:185] يُرِيدُ اللَّهُ أَنْ يُخَفِّفَ عَنْكُمْ وَخُلِقَ الْإِنْسَانُ ضَعِيفًا [النساء:28] هذه إرادة شرعية، قد أراد اليسر، وأمر عباده بما فيه يسرهم، لكن قد يحصل هذا لبعض الناس، وقد لا يحصل اليسر، قد يبتلى بالعسر، قد أراد من الناس أن يصلوا، وأن يصوموا، وأمرهم بهذا، وأن يعبدوه وحده، فمنهم من صلى وصام وعبد الله، ومنهم من كفر وهم الأكثرون، هذه إرادة شرعية. \n\nفالمطيع الموحد اجتمع فيه الإرادتان، وافق إرادة الله الكونية، ووحد الله وأطاعه، ووافق الإرادة الشرعية؛ لأنه بطاعته لله وتوحيده لله قد وافق الإرادة الشرعية أيضًا.\n\nأما العاصي فقد وافق الإرادة الكونية، ولكنه خالف الإرادة الشرعية، والأمر الشرعي، وهكذا الكافر.","link":"https://binbaz.org.sa/fatwas/3232/الفرق-بين-الارادة-الكونية-القدرية-والارادة-الدينية-الشرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1574.mp3","categories":["القضاء والقدر"]},{"id":7341,"question":"كثير من الناس لما يعمل المعصية، ويقام عليه الحد، ويدخل السجن، يقول: قضاء الله وقدره، الحمد لله، هذا الله كتبه علي؟","title":"وجوب الإيمان بالقدر للمذنب مع التوبة","answer":"الجواب: هذا كتبه الله، وعليه التوبة مع ذلك، هو قضاء وقدر، ولكن عليه التوبة، يحمد الله على ما قدر من كونه عوقب عليها، وأقيم عليه الحد، وكونه صبر على ما قضى الله، ويرضى بقضاء الله، لكن عليه أن يبادر بالتوبة والندم والإقلاع وألا يعود، قدر الله لا يجعله يصر على المعصية ولا يعود إليها، ولكن قدر الله يعزي نفسه، ويحمد الله على ما قضى وقدر، وأنه أقيم عليه الحد، وأنه تاب إلى الله، وأنه رجع إلى الله  ولا يجعل القدر حجة على المعصية.","link":"https://binbaz.org.sa/fatwas/3432/وجوب-الايمان-بالقدر-للمذنب-مع-التوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1740.mp3","categories":["القضاء والقدر"]},{"id":7354,"question":"هل يعتبر ما يترتب على الحسد من آثار سيئة قدرًا؟ وما هو رأي الدين في الحسد مع اعتبار أن الحسد ذكر في كتاب الله الكريم؟","title":"بيان أن الحسد وما يترتب عليه أنه قدر","answer":"الجواب: كل موجود فهو بقدر الله، الحسد وغيره كلما يوجد في الوجود من ضار أو نافع، أو طاعة أو معصية، من مرض أو غيره كله قد سبق به علم الله : إِنَّا كُلَّ شَيْءٍ خَلَقْنَاهُ بِقَدَرٍ [القمر:49]، مَا أَصَابَ مِنْ مُصِيبَةٍ فِي الْأَرْضِ وَلَا فِي أَنْفُسِكُمْ إِلَّا فِي كِتَابٍ مِنْ قَبْلِ أَنْ نَبْرَأَهَا إِنَّ ذَلِكَ عَلَى اللَّهِ يَسِيرٌ [الحديد:22]، مَا أَصَابَ مِنْ مُصِيبَةٍ إِلَّا بِإِذْنِ اللَّهِ وَمَنْ يُؤْمِنْ بِاللَّهِ يَهْدِ قَلْبَهُ [التغابن:11].  فالرب  قد كتب كل شيء: الحسد، والسحر، والظلم، والمرض، والعين، العين حق، وغير هذا كل ذلك بقضاء الله، لا يقع شيء في ملك الله إلا وقد سبق به علمه  وقد شرع من العلاج والأدوية ما ينفع الله به العباد، إذا شاء  ولهذا قال في الحديث الصحيح، يقول النبي ﷺ: ما أنزل الله داء إلا أنزل له شفاء، علمه من علمه، وجهله من جهله.","link":"https://binbaz.org.sa/fatwas/3436/بيان-ان-الحسد-وما-يترتب-عليه-انه-قدر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1743.mp3","categories":["القضاء والقدر"]},{"id":7355,"question":"هل الإنسان مسير أم مخير؟ وما الفرق بين الإرادة، والمشيئة الكونية والشرعية مع ضرب الأمثلة على ذلك؟","title":"بيان صحة القول بأن الإنسان مسير أو مخير","answer":"الجواب: الإنسان مسير ومخير جميعًا، مخير؛ لأن له قدرة، وله اختياره، وله عقل، وله مشيئة، وهو يعمل بمشيئته وإرادته، يطيع بمشيئته، ويعصي بمشيئته، وهو مسؤول وهو مخاطب، ومكلف، وهو مخير بهذا، إن شاء أطاع، وإن شاء عصى، ولهذا تعلقت به التكاليف، فأثيب على الطاعة، وعوقب على المعصية. وهو مسير من جهة أنه لم يخرج عن قدر الله، قدر الله السابق لن يخرج عنه، فهو يصير إلى قدر الله مثل ما قال النبي ﷺ: اعملوا فكل ميسر لما خلق له، فهو ميسر لما خلق له من سعادة، ومن شقاوة، لكن ليس له عذر في ذلك، عليه أن يعمل، وعليه أن يجتهد، فهو له اختيار، وله عقل، وله مشيئة، وله إرادة كما قال تعالى: لِمَنْ شَاءَ مِنْكُمْ أَنْ يَسْتَقِيمَ  ۝  وَمَا تَشَاءُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ [التكوير:28، 29]، وقال: تُرِيدُونَ عَرَضَ الدُّنْيَا وَاللَّهُ يُرِيدُ الْآخِرَةَ [الأنفال:67]، فَمَنْ شَاءَ ذَكَرَهُ  ۝  وَمَا يَذْكُرُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ [المدثر:55، 56]، وقال : إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ [النور:30]، إِنَّهُ خَبِيرٌ بِمَا تَفْعَلُونَ [النمل:88]، إِنَّ اللَّهَ خَبِيرٌ بِمَا تَعْمَلُونَ [المائدة:8] فله عمل، وله صنعة، وله فعل، ولو ضربه أحد؛ لخاصمه، وطلب الانتقام، وقد ينتقم بلا محاكمة.  المقصود: أن له اختياره، وله مشيئة، وإرادة، فهو مكلف بهذا، ومأمور منهي، ولكن مع هذا كله هو ميسر، هو ميسر لما خلق له من شقاوة أو سعادة، لن يخرج عن قدر الله الذي أختص الله بعلمه . والإرادة إرادتان: إرادة شرعية، وهي مقتضى الأمر، وقد أمر العباد بطاعته وعبادته وأراد منهم ذلك شرعًا، فمنهم من عصى ومنهم من أطاع، وهناك إرادة كونية بمعنى المشيئة، وهذه الإرادة الكونية لا يخرج عنها أحد، بل هي نافذة، الإرادة الكونية مع المشيئة نافذة كما قال : إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَنْ يَقُولَ لَهُ كُنْ فَيَكُونُ [يس:82] هذه الإرادة الكونية، وقال سبحانه: فَمَنْ يُرِدِ اللَّهُ أَنْ يَهْدِيَهُ يَشْرَحْ صَدْرَهُ لِلْإِسْلَامِ وَمَنْ يُرِدْ أَنْ يُضِلَّهُ يَجْعَلْ صَدْرَهُ ضَيِّقًا حَرَجًا كَأَنَّمَا يَصَّعَّدُ فِي السَّمَاءِ [الأنعام:125] هذه الإرادة الكونية بمعنى المشيئة.  وأما الإرادة الشرعية فهي بمعنى الأمر، مثل ما في حديث: أن الله يقول لبعض الناس يوم القيامة: لو كانت لك الدنيا بما فيها أكنت مفتديًا بها من عذاب الله؟ فيقول: نعم، فيقول الله: قد أردت منك ما هو أسهل من ذلك، أردت منك أن لا تشرك بي، فأبيت إلا الشرك أردت، يعني شرعًا، يعني أمرتك ليس معناه الإرادة الكونية لا، هذه إرادة شرعية، يعني أردت منك أن لا تشرك فأبيت، يعني أمرتك بهذا، ولكنك أطعت هواك وشيطانك.","link":"https://binbaz.org.sa/fatwas/3430/بيان-صحة-القول-بان-الانسان-مسير-او-مخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1738.mp3","categories":["القضاء والقدر"]},{"id":8021,"question":"هذه رسالة وردتنا من قرية السادة من العراق ديالا يقول فيها مرسلها: يقال: إن الإنسان مسير، ويقال: إنه مخير، فهل صحيح أنه مخير أو أنه مسير، وإذا كان مسير فلماذا جعل الله النار للملحدين مع أنه هو الذي كتب عليهم الإلحاد؟","title":"معنى قول العلماء: (الإنسان مسير ومخير)","answer":"الجواب: الإنسان له وصفان: مسير ومخير، مسير ليس له خروج عن قدر الله ، الله  قدر مقادير الخلق قبل أن يخلقهم بخمسين ألف سنة كما جاء به الحديث الشريف، والقدر أمر ثابت وهو من أصول الإيمان فإن النبي عليه الصلاة والسلام لما سأله جبرائيل عن الإيمان قال في جوابه: أن تؤمن بالله، وملائكته، وكتبه، ورسله، واليوم الآخر، وتؤمن بالقدر خيره وشره فالإيمان بالقدر من أصول الإيمان والله قدر الأشياء وكتبها سبحانه قبل أن يخلق الناس، خلق العبد وقدر رزقه وأجله وشقاوته وسعادته، هذا أمر معلوم وقد أجمع عليه أهل السنة والجماعة ، فهو مسير من هذه الحيثية، من جهة أنه لا يخرج عن قدر الله ولكنه ميسر أيضاً لما خلق له، فإن الصحابة  لما أخبرهم النبي ﷺ أنه ما من الناس أحد إلا وقد علم مقعده من الجنة ومقعده من النار، فقالوا: يا رسول الله ففيم العمل؟! قال: اعملوا فكل ميسر لما خلق له فأما أهل السعادة فييسرون لعمل أهل السعادة، وأما أهل الشقاوة فييسرون لعمل الشقاوة، ثم تلا قوله سبحانه: فَأَمَّا مَنْ أَعْطَى وَاتَّقَى ۝ وَصَدَّقَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْيُسْرَى ۝ وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى ۝ وَكَذَّبَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْعُسْرَى [الليل:5-10] فبين عليه الصلاة والسلام أن جميع الأمور مقدرة، وأن أعمال العبد وشقاوته وسعادته وسائر شئونه قد مضى به علم الله وقد كتبه الله ، فليس للعباد خروج عما كتب في اللوح المحفوظ وعما قدره الله عليهم ، وهو من هذه الحيثية مسير وميسر أيضاً.\nأما من جهة التخيير فالله جل وعلا أعطاه عقلاً وسمعاً وبصراً وأدوات، فهو بها يعرف ما يضره وما ينفعه وما يناسبه وما لا يناسبه، فإذا أتى الطاعة فقد أتاها عن اختيار، وإذا أتى المعصية فقد أتاها عن اختيار، فليس بمجبور ولا مكره، بل له عقل ينظر به ويميز به بين الضار والنافع، والخير والشر، والصالح والطالح، وله سمع يسمع، وله بصر يبصر به، وله أدوات من يد يأخذ بها ويعطي، ورجل يسير عليها إلى غير ذلك، فهو بهذا مخير، هو المصلي وهو الصائم، وهو الزاني والسارق، وهو الذاكر والغافل، كل هذا من أعماله فأعماله تنسب إليه وله اختيار وله إرادة كما قال : لِمَنْ شَاءَ مِنْكُمْ أَنْ يَسْتَقِيمَ ۝ وَمَا تَشَاءُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ رَبُّ الْعَالَمِينَ [التكوير:28-29] .. فَمَنْ شَاءَ ذَكَرَهُ ۝ وَمَا يَذْكُرُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ [المدثر:55-56]، تُرِيدُونَ عَرَضَ الدُّنْيَا وَاللَّهُ يُرِيدُ الآخِرَةَ [الأنفال:67] .. إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ [النور:30].. إِنَّ اللَّهَ خَبِيرٌ بِمَا تَعْمَلُونَ [المائدة:8] إن الله بما تعملون خبير، إن الله خبير بما تفعلون فنسب فعلهم إليهم.\nقال: وَالصَّائِمِينَ وَالصَّائِمَاتِ [الأحزاب:35] .. وَالذَّاكِرِينَ اللَّهَ كَثِيرًا وَالذَّاكِرَاتِ [الأحزاب:35] بعدما ذكر ما قبلها في قوله سبحانه: إِنَّ الْمُسْلِمِينَ وَالْمُسْلِمَاتِ وَالْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ وَالْقَانِتِينَ وَالْقَانِتَاتِ وَالصَّادِقِينَ وَالصَّادِقَاتِ [الأحزاب:35] الآية، فأفعالهم تنسب إليهم خيرها وشرها، فالعبد هو الصائم وهو الذاكر وهو الغافل وهو العامل وهو المصلي إلى غير ذلك، فيؤجر على طيب عمله الذي أراد به وجه الله، ويأثم على ما فعله من الشر؛ لأنه مختار عامد لهذا الشيء، فإذا فعل ما شرع الله عن إخلاص ومحبة لله آجره الله؛ من صلاة، وصوم، وصدقة، وحج، وأمر بمعروف ونهي عن منكر وغير ذلك، وإذا فعل ما نهى الله عنه من السرقة، والزنا، والقطيعة للرحم، والعقوق، وشهادة الزور وما أشبه ذلك أخذ بذلك أيضاً، وأثم في ذلك، واستحق العقاب؛ لأن هذا من فعله واختياره، ولا يمنع ذلك كونه قد قدر سبق به علم الله لا يمنع، فقد سبق علم الله بكل شيء ، ولكن العبد يختار ويريد وله مشيئة، فإذا شاء المعصية وأرادها وفعلها أخذ بها، وإذا شاء الطاعة وأرادها وفعلها أجر عليها، فهو مخير ومسير وتعبير السنة «ميسر» وهكذا تعبير الكتاب: فَسَنُيَسِّرُهُ لِلْيُسْرَى [الليل:7] فالتعبير بميسر أولى من المسير، كما جاءت به السنة، ويقال: مسير كما قال الله جل وعلا: هُوَ الَّذِي يُسَيِّرُكُمْ فِي الْبَرِّ وَالْبَحْرِ [يونس:22] فهو يسير عباده أينما شاء  وهو الميسر جل وعلا عبده لما يشاء، وهو سبحانه الذي أعطاه العقل وأعطاه القدرة على الفعل والعمل، فهو من جهة مسير وميسر ولن يخرج عن قدر الله، ومن جهة أخرى هو مخير وله مشيئة وله اختيار وكل هذا واقع، وبهذا قامت عليه الحجة، وانقطعت المعذرة، واستحق الثواب والعقاب على أفعاله الطيبة والخبيثة، فالطيبة له ثوابها والخبيثة عليه وزرها، وبهذا يتضح معنى المسير وميسر ومعنى المخير. نعم.","link":"https://binbaz.org.sa/fatwas/5584/معنى-قول-العلماء-الانسان-مسير-ومخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_077/07702.mp3","categories":["القضاء والقدر"]},{"id":10970,"question":"الفقرة الأخيرة في رسالة هذه السائلة م. الغامدي سماحة الشيخ تقول: ما الفرق بين القضاء والقدر؟","title":"الفرق بين القضاء والقدر","answer":"الجواب:  القضاء والقدر هو القضاء شيء واحد، القضاء والقدر هو الشيء الذي قضاه الله سابقًا، وقدره سابقًا، يقال له: القضاء، ويقال له: القدر، يعني ما سبق في علم الله أنه قدره من موت وحياة، وعز وذل، وأمن وخوف، وغير ذلك، كله يسمى قضاءًا ويسمى قدرًا.  المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9148/الفرق-بين-القضاء-والقدر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_286/28614.mp3","categories":["القضاء والقدر"]},{"id":11274,"question":"السائل يوسف عبد اللطيف العباد من الدمام يقول في هذا  كثيرًا ما نسمع.الشيخ: يوسف؟المقدم: يوسف عبد اللطيف العباد من الدمام يقول: كثيرًا ما نسمع هذه الأيام عبارة شاءت الأقدار أو شاءت الظروف، فهل في هذه العبارات شرك بالله ؟","title":"حكم قول: شاءت الأقدار أو شاءت الظروف","answer":"الجواب:  لا يجوز هذا الكلام، شاءت الظروف، أو شاءت الأقدار، كل هذا لا يصلح، قل: شاء الله سبحانه، شاء ربنا، شاء الله، شاء الرحمن، شاء الملك العظيم، شاء ربنا، قال جل وعلا: وَمَا تَشَاءُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ [الإنسان:30]، وَلَوْلا إِذْ دَخَلْتَ جَنَّتَكَ قُلْتَ مَا شَاءَ اللَّهُ لا قُوَّةَ إِلَّا بِاللَّهِ [الكهف:39].  المقصود: أن المشيئة تنسب إليه سبحانه لا إلى الظروف ولا إلى الأوقات ولا إلى الأقدار ولا إلى غير هذا من الشئون، لكن تنسب إلى الله وحده سبحانه وتعالى. نعم.","link":"https://binbaz.org.sa/fatwas/9449/حكم-قول-شاءت-الاقدار-او-شاءت-الظروف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_292/29204.mp3","categories":["القضاء والقدر"]},{"id":11725,"question":"المستمعة (أ. م) من الأردن بعثت تسأل وتقول: ما رأي سماحتكم في سب الإنسان حظه، أو بخته؛ لأن هذا كثيرًا ما يتردد على ألسنة البعض، هل في ذلك إثم؟","title":"حكم سب الإنسان حظه وبخته","answer":"الجواب:  نعم، لا يجوز سب الحظ والبخت، لا يجوز سبه، بل يقول: (قدر الله وما شاء فعل) ويسأل ربه التوفيق والإعانة، وأن يسهل أموره، ويقضي حاجاته، ولا يسب حظه، ولا بخته، السب ممنوع، لا يسب الإنسان زمانه، ولا حظه وبخته، ولا مكانه، بل يستغفر الله، ويسأل ربه التوفيق، ويتوب إلى الله من معاصيه، فما أصابه إلا ذنب، ويجتهد في التوبة إلى الله مثلما قال -جل وعلا-: وَمَا أَصَابَكُمْ مِنْ مُصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُوا عَنْ كَثِيرٍ [الشورى:30] وقال سبحانه: وَمَا أَصَابَكَ مِنْ سَيِّئَةٍ فَمِنْ نَفْسِكَ [النساء:79]. المقصود: أن المؤمن والمؤمنة عليهما أن يتوبا إلى الله دائمًا، وأن يحاسبا أنفسهما، وأن يحذرا المعصية من سب، أو غيره، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9908/حكم-سب-الانسان-حظه-وبخته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_421/42106.mp3","categories":["القضاء والقدر"]},{"id":12433,"question":"رسالة مطولة بعض الشيء من إحدى الأخوات المستمعات تقول أم خالد من مكة المكرمة، الرسالة فيها شيء من المعاناة سماحة الشيخ، وإن كانت مطولة أستأذنكم بعض الشيء، تقول: إنها امرأة متزوجة منذ عشرين سنة تقريبًا، ومعها الآن سبعة عيال، أكبرهم يبلغ الثامنة عشرة من عمره، وأصغرهم يبلغ الرابعة من عمره، ومن يوم زواجنا وزوجي لا يصلي، وفي بداية زواجنا صام ثلاثة رمضانات، وصلى فيها فقط، وبعد ذلك الوقت لا يصلي، ولا يصوم، وأنا امرأة أصلي وأصوم وأخاف الله، وكثير من المرات قلت له: أن يصلي، ولكنه كان يقول: إذا كان هو من قبضة اليمين؛ فسوف يدخل الجنة، وإذا كان من قبضة الشمال؛ فسوف يدخل النار، فإذًا صلاته، أو عدمها لا فائدة منها، وفي هذه الأشهر القريبة سمعت من برنامجكم أن المرأة التي تصوم وتصلي لا تجوز للرجل الذي لا يصلي ولا يصوم، فتكلمت معه بهذا الخصوص، وحصلت مشاكل، وبعد ذلك -ومنذ أشهر قليلة- أصبح يصلي مرة، ولا يصلي أخرى، ويؤخر صلاة العصر والعشاء، ولا يذهب إلى المسجد، مع أننا نسمع الأذان، ونحن في البيت، أرجو أن توجهوني كيف أتصرف. ولها أسئلة أخرى متعلقة بنفس الموضوع، هل أقرؤها سماحة الشيخ دفعة واحدة؟الشيخ: ..... بعدين.المقدم: نعم.","title":"حكم الاحتجاج بالقدر في المعاصي","answer":"الجواب:  نسأل الله لنا وله الهداية، نسأل الله لنا وله الهداية، هذا قوله: إن كنت من قبضة اليمين؛ دخلت الجنة إلى آخره هذا غلط لا يحتج بالقدر، الرسول ﷺ لما سألوه: قالوا يا رسول الله! لما قال لهم: ما منكم من أحد إلا وقد علم مقعده من الجنة ومقعده من النار قال الصحابة: يا رسول الله! أفلا نتكل على كتابنا، وندع العمل؟ قال ﷺ: اعملوا فكل ميسر لما خلق له، أما أهل السعادة فسييسرون لعمل أهل السعادة، وأما أهل الشقاوة فسييسرون لعمل أهل الشقاوة، ثم تلا قوله تعالى: فَأَمَّا مَنْ أَعْطَى وَاتَّقَى ۝ وَصَدَّقَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْيُسْرَى ۝ وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى ۝ وَكَذَّبَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْعُسْرَى [الليل:5-10]. فلا يجوز لأحد أن يحتج بالقدر، بل على كل إنسان من رجل وامرأة أن يتقي الله، وأن يعمل بطاعة الله من صلاة وصوم وحج وزكاة، وغير ذلك، وعليه أن يحذر معاصي الله، الله أعطاه عقلًا، وأعطاه سمعًا، وأعطاه بصرًا، لابد أن يستعمل ما أعطاه الله من النعم، ولا يجوز له أن يحتج بالقدر، وهل يمكنه أن يحتج بالقدر فيجلس ولا يأكل ولا يشرب إن كان صادقًا؟! ليجلس لا يأكل ولا يشرب، ويقول: إن كنت كتب الله لي أني أحيا حييت! هو يكذب، لا يستطيع أن يبقى، بل لابد أن يأكل ويشرب. فالمقصود: أن هذا الاحتجاج بالقدر أمر باطل، فلا يجوز أن يحتج بالقدر، لا في أكله وشربه، ولا في جماعه لزوجته، ولا في طلبه للولد، ولا في بره لوالديه، ولا في طلبه للتجارة، ولا في أسفاره، ولا في مزرعته، ولا غير هذا. فهكذا في صلاته، هكذا في صومه، هكذا في أعماله الأخرى، ليس له أن يحتج بالقدر، بل يجب أن يعمل بما أوجب الله، وأن يدع ما حرم الله، كما يجب عليه أن يطلب الرزق، ويتسبب في طلب الرزق الذي يعينه على طاعة الله، ويغنيه عن الناس، بالبيع والشراء، أو بطريق الزراعة، أو النجارة، أو الحدادة، أو الخياطة، أو غير هذا من الأسباب، وليس له أن يحتج بالقدر ويقول: أجلس في بيتي، ولا أفعل الأسباب والرزق يأتيني! هذا غلط ما يقوله عاقل. فهكذا في الصلاة والعبادة لا يجوز أن يترك الصلاة ويقول: أنا إن كنت من أهل السعادة؛ دخلت الجنة، وإلا فأنا من أهل النار، هذا كله باطل، ولا يجوز الاحتجاج بالقدر أبدًا، وهذه حجة المشركين: لَوْ شَاءَ اللَّهُ مَا أَشْرَكْنَا [الأنعام:148] ولم يعذرهم الله . فالواجب على زوجك أن يتقي الله، وأن يراقب الله، وأن يصلي مع المسلمين في المساجد، وأن يحافظ على ذلك، وأن يصوم رمضان، وأن يؤدي زكاة ماله إن كان عنده مال، وأن يحج حج البيت، الحج الواجب، الفريضة وهو مرة في العمر، وأن يبر والديه، وأن يقوم بحق زوجته إلى غير ذلك. والواجب عليك أنت أن تمتنعي منه، ولا تمكنيه من نفسك حتى يتوب إلى الله توبة صادقة، حتى يصلي جميع الأوقات، ما دام لا يصلي؛ فهو كافر، وليس لك أن تمكنيه من نفسك، هذا هو الحق، وهذا هو الصواب من قولي العلماء: أن من تركها؛ كفر، وإن لم يجحد وجوبها؛ لقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر وقال -عليه الصلاة والسلام-: بين الرجل، وبين الكفر والشرك ترك الصلاة في أحاديث أخرى كثيرة تدل على كفر تارك الصلاة، فاتقي الله أنت، واحذري شره، وابتعدي عنه عند أهلك؛ حتى يتوب الله عليه، وإن أبى؛ فارفعي الأمر إلى المحكمة، والمحكمة تنظر في الأمر، ولا تتساهلي في هذا أبدًا، نسأل الله لنا وله الهداية. المقدم: اللهم آمين، سنعود إلى رسالتك يا أم خالد في حلقة قادمة، إن شاء الله تعالى.","link":"https://binbaz.org.sa/fatwas/10632/حكم-الاحتجاج-بالقدر-في-المعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_455/45513.mp3","categories":["القضاء والقدر"]},{"id":12645,"question":"المستمع صلاح علي عبدالعزيز من جمهورية مصر العربية، محافظة سوهاج بعث بعدد من الأسئلة من بينها سؤال يقول فيه: هل الإنسان مخير، أم مسير؟","title":"وجه كون الإنسان مسيراً أو مخيراً","answer":"الجواب:  هو مخير ومسير، هو مخير، قال الله تعالى: لِمَنْ شَاءَ مِنْكُمْ أَنْ يَسْتَقِيمَ ۝ وَمَا تَشَاءُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ رَبُّ الْعَالَمِينَ [التكوير:28-29] وقال تعالى: هُوَ الَّذِي يُسَيِّرُكُمْ فِي الْبَرِّ وَالْبَحْرِ [يونس:22] فهو مسير من جهة أن قدر الله نافذ فيه، وأن الله قد سبق في علمه كلما يفعله العباد، قد قدر الأمور وقضاها  وكتبها عنده، ولكن أعطى العبد عقلًا وسمعًا وبصرًا واختيارًا وفعلًا، فهو يعمل ويكدح بمشيئته وإرادته، ولكنه بذلك لا يخرج عن مشيئة الله، ولا عن قدر الله السابق. وقد قال النبي ﷺ للصحابة -رضي الله عنهم وأرضاهم-: ما منكم من أحد إلا وقد كتب مقعده من الجنة، ومقعده من النار، قالوا: يا رسول الله! أفلا نتكل على الكتاب، وندع العمل؟ قال -عليه الصلاة والسلام-: اعملوا، فكل ميسر لما خلق له، أما أهل السعادة فييسرون لعمل أهل السعادة، وأما أهل الشقاوة فييسروم لعمل أهل الشقاوة ثم تلا قوله سبحانه: فَأَمَّا مَنْ أَعْطَى وَاتَّقَى ۝ وَصَدَّقَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْيُسْرَى ۝ وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى ۝ وَكَذَّبَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْعُسْرَى [الليل:5-10].  فعلى العبد أن يعمل ويكدح ويجتهد في طاعة الله، ويحذر معاصيه  وليس له أن يحتج بالقدر، قدر الله نافذ في عباده، ولكنه جعل للناس أسماعًا وأبصارًا وعقولًا، وأعطاهم قوى، وأمرهم بالأسباب. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10855/وجه-كون-الانسان-مسيرا-او-مخيرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_457/45715.mp3","categories":["القضاء والقدر"]},{"id":13088,"question":"في آخر سؤال لهذه السائلة تقول: لا أدري هل يجوز أن أسأل مثل هذا السؤال، أم لا: هل الإنسان مخير، أم مسير في هذه الحياة؟ وجزاكم الله خيرًا.","title":"الإنسان مخير ومسير في هذه الحياة","answer":"الجواب:  مخير ومسير جميعًا، مخير له أعمال، وله عقل، وله تصرف، وله سمع وبصر، يختار الخير، ويبتعد عن الشر، يأكل ويشرب باختياره، يتجنب ما يضره باختياره، يأتي ما ينفعه باختياره، وهو مسير بمعنى: أنه لا يتعدى القدر هُوَ الَّذِي يُسَيِّرُكُمْ فِي الْبَرِّ وَالْبَحْرِ [يونس:22] وقال تعالى: فَمَنْ شَاءَ فَلْيُؤْمِنْ وَمَنْ شَاءَ فَلْيَكْفُرْ [الكهف:29] .. وَمَا تَشَاءُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ [الإنسان:30] فهو له مشيئة وله اختيار، إِنَّ اللَّهَ خَبِيرٌ بِمَا تَعْمَلُونَ [المائدة:8] .. خَبِيرٌ بِمَا تَفْعَلُونَ [النمل:88] .. كَبُرَ مَقْتًا عِنْدَ اللَّهِ أَنْ تَقُولُوا مَا لا تَفْعَلُونَ [الصف:3] له فعل وله اختيار وله إرادة : تُرِيدُونَ عَرَضَ الدُّنْيَا وَاللَّهُ يُرِيدُ الآخِرَةَ [الأنفال:67] .. لِمَنْ شَاءَ مِنْكُمْ أَنْ يَسْتَقِيمَ * وَمَا تَشَاءُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ [التكوير:28-29]. فمشيئة الله نافذة، وقدره نافذ، فهو من هذه الحيثية مسير، لا يخرج عن قدر الله، وهو مع ذلك مخير، له فعل، وله مشيئة، وله إرادة، يأتي الخير بإرادته، ويدع الشر بإرادته، يأكل بإرادته، ويمسك بإرادته، يسافر بإرادته، ويقيم بإرادته، يخرج إلى الصلاة، وإلى غيرها بإرادته، ويجلس بإرادته؛ ولهذا يستحق العقاب على المعاصي، ويستحق الثواب على الطاعات؛ لأن له اختيار، وله فعل، فهو مثاب على صلاته، وصومه، وصدقاته، وطاعته لله، وأمره بالمعروف، ونهيه عن المنكر، مثاب على هذا إذا فعله لله. ويستحق العقاب على معاصيه، من الزنا.. من التهاون بالصلاة.. من أكل الربا.. الغيبة.. النميمة.. إلى غير ذلك، فله فعل، وله اختيار، ولكنه في فعله واختياره لا يسبق مشيئة الله، ولا يخرج عن قدر الله، نعم. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11305/الانسان-مخير-ومسير-في-هذه-الحياة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_507/50720.mp3","categories":["القضاء والقدر"]},{"id":13351,"question":"له فقرة أخرى يقول يا سماحة الشيخ: هل الدعاء يغير المكتوب عند الله تعالى؟","title":"هل الدعاء يغير المكتوب؟","answer":"الجواب: الدعاء من القدر، والمكتوب لا يتغير، فالقدر قدران: قدر محتوم لا حيلة فيه، وقدر معلق، فيكون بعض القدر معلقًا بالدعاء، فإذا دعا زال المعلق، قد يكون معلقًا أن الله -جل وعلا- يتوب عليه إذا صلى.. إذا صام.. إذا فعل كذا، فهذا قدر معلق، الله -جل وعلا- يرفعه عنه بما فعل من الطاعات، والأعمال الصالحات، والتوبة. فالأقدار تعالج بالأقدار، مثلما قال عمر لما أشار عليه الصحابة في غزواته إلى الشام، ووقع الطاعون، أشاروا عليه بالرجوع، وأشار بعضهم بعدم الرجوع، ثم استقر أمره على الرجوع من المدينة، وعدم القدوم على الطاعون، فقالوا: تفر من قدر الله؟ فقال : نفر من قدر الله إلى قدره\" الله أمرنا بأن لا نقدم عليه، لا نقدم على هذا المرض، فإذا تركنا القدوم عليه؛ فقد فررنا من قدر الله إلى قدر الله. ثم جاء عبدالرحمن بن عوف  فأخبر عمر أن الرسول ﷺ أمر بأن لا يقدم عليه، ففرح عمر بذلك، وأن الله وفقه لما جاء به النص بعدما استشار الصحابة. وهكذا الإنسان تصيبه الحمى، فيتعاطى الأسباب، يفر من قدر الله إلى قدر الله، يجوع يأكل حتى يزول الجوع، يفر من قدر الله إلى قدر الله، يصيبه الحر، فيشرب الماء البارد، أو يتروش، يفر من قدر الله إلى قدر الله، يصيبه المرض في عينيه، فيعالجها بأنواع العلاج، يفر من قدر الله إلى قدر الله، وهكذا أنواع العلاج كلها تفر من قدر الله إلى قدر الله. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11637/هل-الدعاء-يغير-المكتوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_523/52308.mp3","categories":["القضاء والقدر"]},{"id":13405,"question":"هذا السائل سوداني رمز لاسمه بـ (أ. أ) يعمل في الدمام يقول: هل الإنسان مسير، أم مخير في أعماله الصالحة، وغير الصالحة؟ وجهونا في ضوء هذا السؤال.","title":"هل الإنسان مسير أم مخير في أعماله الصالحة وغير الصالحة؟","answer":"الجواب: الإنسان مسير ومخير، مسير لا يخرج عن قدر الله، مهما فعل؛ فهو تحت قدر الله، ومخير؛ لأن له عقلًا وفعلًا واختيارًا، أعطاه الله عقلًا، وأعطاه الله فعلًا واختيارًا، فهو يفعل باختياره، ويدع باختياره، ولهذا تعلقت به التكاليف واستحق الجزاء على أعماله، الطيب بالجزاء الحسن، والرديء بالجزاء السوء هَلْ جَزَاءُ الإِحْسَانِ إِلَّا الإِحْسَانُ [الرحمن:60]وَجَزَاءُ سَيِّئَةٍ سَيِّئَةٌ مِثْلُهَا [الشورى:40]، وَلِلَّهِ مَا فِي السَّمَوَاتِ وَمَا فِي الأَرْضِ لِيَجْزِيَ الَّذِينَ أَسَاءُوا بِمَا عَمِلُوا وَيَجْزِيَ الَّذِينَ أَحْسَنُوا بِالْحُسْنَى [النجم:31] ويقول -جل وعلا-: فَأَمَّا مَنْ أَعْطَى وَاتَّقَى ۝ وَصَدَّقَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْيُسْرَى ۝ وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى ۝ وَكَذَّبَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْعُسْرَى [الليل:5-10] ويقول -جل وعلا-: هُوَ الَّذِي يُسَيِّرُكُمْ فِي الْبَرِّ وَالْبَحْرِ [يونس:22]. والنبي سئل لما قال -عليه الصلاة والسلام- للصحابة: ما منكم من أحد إلا وقد علم مقعده من الجنة، ومقعده من النار وفي اللفظ الآخر: قد كتب مقعده من الجنة، ومقعده من النار قالوا: يا رسول الله! ففيم العمل؟ -مادامت مقاعدنا معلومة، ومادمنا مكتوبين فلم العمل؟- قال: اعملوا فكل ميسر لما خلق له؛ أما أهل السعادة فييسرون لعمل أهل السعادة، وأما أهل الشقاوة فييسرون لعمل أهل الشقاوة ثم قرأ قوله سبحانه: فَأَمَّا مَنْ أَعْطَى وَاتَّقَى ۝ وَصَدَّقَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْيُسْرَى ۝ وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى ۝ وَكَذَّبَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْعُسْرَى [الليل:5-10] وقال تعالى: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:3] وقال تعالى: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] وقال تعالى: إِنْ تَتَّقُوا اللَّهَ يَجْعَلْ لَكُمْ فُرْقَانًا [الأنفال:29]. فدل على أن الأسباب يترتب عليها مسبباتها، فمن اتقى الله؛ يسر الله أموره، وفرج كرباته، ورزقه من حيث لا يحتسب، ومن عصى الله، وخالف أوامره؛ فقد تعرض لغضب الله، وسخطه، وتعسير أموره، نسأل الله العافية. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11695/هل-الانسان-مسير-ام-مخير-في-اعماله-الصالحة-وغير-الصالحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_526/52603.mp3","categories":["القضاء والقدر"]},{"id":15266,"question":"ما حكم قول الإنسان: حصل هذا الشيء صدفة؟","title":"حكم قول: حصل هذا الشيء صدفة","answer":"الجواب: ليس فيه شيء؛ لأن المراد حصل من دون ميعاد له، مثل وافق فلان في الطريق، فسلم عليه، ما واعده، وافقه عند إنسان زاره ففرح به، ليس عن موعد، الصدفة عن غير ميعاد، يعني: حصل الشيء عن غير ميعاد بينه وبين زيد أو عمرو، أو فلان أو فلان، هذا معنى الصدفة، يعني: من غير ميعاد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13763/حكم-قول-حصل-هذا-الشيء-صدفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_497/49708.mp3","categories":["القضاء والقدر"]},{"id":15571,"question":"هذه رسالة من المستمع جهاد رشيد، من العراق، محافظة التأميم، سؤاله الأول يقول: هناك قسم من الناس يقولون: إن كل الأعمال التي يعملها الإنسان هي من إرادة الله، رجاؤنا أن توضحوا هذه المسألة هل الإنسان مخير أم مسير؟","title":"هل الإنسان مسير أم مخير؟ وهل الأعمال التي يعملها هي من إرادة الله؟","answer":"الجواب: هذه المسألة قد يلتبس أمرها على بعض الناس، والإنسان مخير ومسير؛ مخير لأن الله أعطاه إرادة اختيارية، وأعطاه مشيئة يتصرف بها في أمور دينه ودنياه، فليس مجبرًا ومقهورًا، لا، بل له اختيار وله مشيئة وله إرادة، كما قال : لِمَنْ شَاءَ مِنْكُمْ أَنْ يَسْتَقِيمَ ۝ وَمَا تَشَاءُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ رَبُّ الْعَالَمِينَ [التكوير:28-29] وقال سبحانه: فَمَنْ شَاءَ ذَكَرَهُ ۝ وَمَا يَذْكُرُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ [المدثر:55-56] وقال سبحانه: تُرِيدُونَ عَرَضَ الدُّنْيَا وَاللَّهُ يُرِيدُ الآخِرَةَ وَاللَّهُ عَزِيزٌ حَكِيمٌ [الأنفال:67] وقال سبحانه: مَنْ كَانَ يُرِيدُ الْعَاجِلَةَ عَجَّلْنَا لَهُ فِيهَا مَا نَشَاءُ لِمَنْ نُرِيدُ [الإسراء:18]. فالعبد له اختيار، وله إرادة، وله مشيئة، لكن هذه الإرادة وهذه المشيئة لا تقع إلا بعد مشيئة الله  فهو -جل وعلا- المتصرف في عباده، والمدبر لشؤونهم؛ فلا يستطيعون أن يشاؤوا شيئًا، أو يريدوا شيئًا إلا بعد مشيئة الله له، وإرادته الكونية القدرية ، فما يقع في العباد، وما يقع منهم، كله بمشيئة من الله سابقة، وقدر سابق، فالأعمال والأرزاق والآجال والحروب، وانتزاع ملك، وقيام ملك، وسقوط دولة، وقيام دولة؛ كله بمشيئة الله ، كما قال : قُلِ اللَّهُمَّ مَالِكَ الْمُلْكِ تُؤْتِي الْمُلْكَ مَنْ تَشَاءُ وَتَنْزِعُ الْمُلْكَ مِمَّنْ تَشَاءُ وَتُعِزُّ مَنْ تَشَاءُ وَتُذِلُّ مَنْ تَشَاءُ بِيَدِكَ الْخَيْرُ إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ [آل عمران:26] . فالمقصود: أنه -جل وعلا- له إرادة في عباده ومشيئة لا يتخطاها العباد، ويقال لها: الإرادة الكونية، والمشيئة، فما شاء الله كان، وما لم يشأ لم يكن، ومن هذا قوله سبحانه: فَمَنْ يُرِدِ اللَّهُ أَنْ يَهدِيَهُ يَشْرَحْ صَدْرَهُ لِلإِسْلامِ وَمَنْ يُرِدْ أَنْ يُضِلَّهُ يَجْعَلْ صَدْرَهُ ضَيِّقًا حَرَجًا كَأَنَّمَا يَصَّعَّدُ فِي السَّمَاءِ [الأنعام:125] وقال تعالى: إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَنْ يَقُولَ لَهُ كُنْ فَيَكُونُ [يس:82]. فالعبد له اختيار، وله إرادة، ولكن اختياره وإرادته تابعتان لمشيئة الله وإرادته ، فالطاعات بقدر الله، والعبد مشكور عليها ومأجور، والمعاصي بقدر الله، والعبد ملوم عليها ومأزور وآثم، والحجة قائمة الحجة لله وحده : قُلْ فَلِلَّهِ الْحُجَّةُ الْبَالِغَةُ فَلَوْ شَاءَ لَهَدَاكُمْ أَجْمَعِينَ [الأنعام:149] ، وَلَوْ شَاءَ اللَّهُ لَجَمَعَهُمْ عَلَى الْهُدَى فَلا تَكُونَنَّ مِنَ الْجَاهِلِينَ [الأنعام:35] فهو سبحانه لو شاء لهداهم جميعًا، ولكن له الحكمة البالغة، حيث جعلهم قسمين: كافرًا ومسلمًا، وكل شيء بإرادته  ومشيئته، فينبغي للمؤمن أن يعلم هذا جيدًا، وأن يكون على بينة في دينه، فهو مختار، له إرادة، وله مشيئة، يستطيع يأكل يشرب، يضارب يتكلم يطيع يعصي يسافر يقيم يعطي فلانًا ويحرم فلانًا، إلى غير هذا، هو له مشيئة في هذا، وله قدرة، ليس مقهورًا ولا ممنوعًا، ولكن هذه الأشياء التي تقع منه لا تقع إلا بعد سبقها من الله، بعد أن تسبق إرادة الله -جل وعلا- ومشيئته لهذا العمل لِمَنْ شَاءَ مِنْكُمْ أَنْ يَسْتَقِيمَ ۝ وَمَا تَشَاءُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ [الإنسان:29-30].\nفهو سبحانه المسير لعباده، كما قال : هُوَ الَّذِي يُسَيِّرُكُمْ فِي الْبَرِّ وَالْبَحْرِ [يونس:22] فهو المسير لعباده، وبيده نجاتهم وسعادتهم وضلالهم وهلاكهم، هو المتصرف في عباده، يهدي من يشاء، ويضل من يشاء ، يعطي من يشاء، ويحرم من يشاء، يسعد من يشاء، ويشقي من يشاء، لا أحد يعترض عليه . فينبغي لك -يا عبد الله- أن تكون على بصيرة في هذا الأمر، وأن تتدبر كتاب ربك، وسنة نبيك -عليه الصلاة والسلام-؛ حتى تعلم هذا واضحًا في الآيات والأحاديث، فالعبد مختار وله مشيئة، وله إرادة، وفي نفس الأمر ليس له شيء من نفسه، بل هو مملوك لله  مقدور لله ، يدبره كيف يشاء ، مشيئة الله نافذة، وقدره السابق ماض فيه، ولا حجة له بالقدر السابق، فالله يعلم أحوالهم ولا تخفى عليه خافية ، وهو المدبر لعباده، والمصرف لشؤونهم -جل وعلا-، وقد أعطاهم إرادة ومشيئة واختيارًا يتصرفون به، نعم.","link":"https://binbaz.org.sa/fatwas/14111/هل-الانسان-مسير-ام-مخير-وهل-الاعمال-التي-يعملها-هي-من-ارادة-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_703/nour_70309.mp3","categories":["القضاء والقدر"]},{"id":16195,"question":"رسالة من إحدى الأخوات المستمعات، تقول أم حازم من الجبيل الصناعية، لها جمع من الأسئلة في أحدها تقول: هل الأجل مكتوب عند مرحلة معينة للإنسان؟","title":"هل أجل الإنسان مكتوب عند مرحلة معينة؟","answer":"الجواب: الله  هو الذي يعلم الآجال ووقتها -جل وعلا- ليس له حد محدود بالنسبة إلى المخلوق، ولكنه له حد عند الله، كل واحد له أجل محدود، متى وصل إليه انتهى، لكن المخلوق ما يعرف هذه الأشياء، وليس له حد محدود بالنسبة للإنسان، قد يبلغ المائة، وقد يكون أقل، وقد يكون أكثر، فهذا شيء إلى الله -جل وعلا- لهم آجال ضربها  لهم إلى أجل مسمى، ثم إذا جاء الأجل انتهى وَلَنْ يُؤَخِّرَ اللَّهُ نَفْسًا إِذَا جَاءَ أَجَلُهَا [المنافقون:11] فَإِذَا جَاءَ أَجَلُهُمْ لا يَسْتَأْخِرُونَ سَاعَةً وَلا يَسْتَقْدِمُونَ [الأعراف:34]. فالمقصود: أن الآجال لها حدود عند الله  لكن المخلوق لا يعرفها، ولا يدري عنها، متى جاء الأجل؛ قبضه الله، نعم. المقدم: جزاكم الله خيرًا، عندما يقترب الأجل هل يشعر الإنسان؟ أم يفاجأ به عندما يحضره الموت؟  الشيخ: الإنسان لا يعلم الغيب، ولا يشعر بالأجل، لكن قد يعرف الأمارات إذا رأى المرض الشديد، أو الجرح الشديد، قد يحس بأن هذا في الغالب سوف يقضي عليه، وسوف يحصل بعده الموت، وإلا فالعلم عند الله  لكن الإنسان على حسب حال المرض، قد يظن الموت من أمراض ظاهرة خطيرة، وقد يظن الموت، ولا يحصل الموت، يبرئه الله ويعافيه  فالأمر بيده -جل وعلا- وهو الذي عنده العلم بالغيب  لكن الأمراض تختلف، والجروح تختلف، فقد يكون المرض خطيرًا، والجرح خطيرًا، ويكون الظن أنه يموت فيه الإنسان، وقد يبطل الظن، ولا يموت الإنسان بذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14910/هل-اجل-الانسان-مكتوب-عند-مرحلة-معينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_806/nour_80617.mp3","categories":["القضاء والقدر"]},{"id":16767,"question":"أما الرسالة التالية فهي رسالة المستمع يونس النور عثمان يسأل ويقول: أرجو أن تتفضلوا بإجابتي عن السؤال التالي: هل الإنسان في هذه الحياة مسير، أو مخير؟ مع اصطحاب جميع الأدلة. جزاكم الله خيرًا.","title":"هل الإنسان في هذه الحياة مسير أم مخير؟","answer":"الجواب: الإنسان مخير، ومسير جميعًا، له الوصفان: هو مخير؛ لأن الله أعطاه عقل، وأعطاه مشيئة، وأعطاه إرادة يتصرف بها؛ فيختار النافع، ويدع الضار، يختار الخير، ويدع الشر، يختار ما ينفعه، ويدع ما يضره، كما قال تعالى: لِمَنْ شَاءَ مِنْكُمْ أَنْ يَسْتَقِيمَ ۝ وَمَا تَشَاءُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ رَبُّ الْعَالَمِينَ [التكوير:28-29] قال : تُرِيدُونَ عَرَضَ الدُّنْيَا وَاللَّهُ يُرِيدُ الآخِرَةَ [الأنفال:67]. فالناس لهم إرادة، ولهم مشيئة، ولهم أعمال، قال تعالى: إِنَّ اللَّهَ خَبِيرٌ بِمَا تَعْمَلُونَ [المائدة:8].. إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ [النور:30] فلهم أعمال ولهم إرادات، ولهم مشيئة، فهم مخيرون، فإذا فعلوا الخير؛ استحقوا الجزاء من الله، فضلًا منه  وإذا فعلوا الشر؛ استحقوا العقاب، فهم إذا فعلوا الطاعات فعلوها باختيارهم، ولهم الأجر عليها، وإن فعلوا المعاصي فعلوها باختيارهم، وعليهم وزرها، وإثمها، والقدر ماضٍ فيهم، هم أيضًا مسيرون بقدر سابق، قال -جل وعلا-: هُوَ الَّذِي يُسَيِّرُكُمْ فِي الْبَرِّ وَالْبَحْرِ [يونس:22]. قال النبي ﷺ: كل شيء بقدر، حتى العجز، والكيس قال سبحانه: مَا أَصَابَ مِنْ مُصِيبَةٍ فِي الأَرْضِ وَلا فِي أَنْفُسِكُمْ إِلَّا فِي كِتَابٍ مِنْ قَبْلِ أَنْ نَبْرَأَهَا [الحديد:22] قال -جل وعلا-: مَا أَصَابَ مِنْ مُصِيبَةٍ إِلَّا بِإِذْنِ اللَّهِ وَمَنْ يُؤْمِنْ بِاللَّهِ يَهْدِ قَلْبَهُ [التغابن:11]. ولما سأل جبرائيل النبي ﷺ عن الإيمان؟ قال: الإيمان أن تؤمن بالله، وملائكته، وكتبه، ورسله، واليوم الآخر، وتؤمن بالقدر خيره وشره وقال -عليه الصلاة والسلام-: إن الله قدر مقادير الخلائق قبل أن يخلق السماوات والأرض بخمسين ألف سنة، وعرشه على الماء فالله قدر الأشياء سابقًا، وعلم أهل الجنة، وأهل النار، وقدر الخير، والشر، والطاعات، والمعاصي، وكل إنسان يسير فيما قدر الله له، وكل ميسر لما خلق له. في الصحيحين عن النبي ﷺ أنه قال لأصحابه ذات يوم: ما منكم من أحد إلا وقد بين مقعده من الجنة، ومقعده من النار قالوا: يا رسول الله، ففيم العمل؟ ففيم العمل يعني: ما دامت مقاعدنا معروفة من الجنة والنار، ففيم العمل؟ قال -عليه الصلاة والسلام-: اعملوا فكل ميسر لما خلق له، أما أهل السعادة فييسرون لعمل أهل السعادة، وأما الشقاوة فييسرون لعمل أهل الشقاوة ثم تلا قوله سبحانه: فَأَمَّا مَنْ أَعْطَى وَاتَّقَى ۝ وَصَدَّقَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْيُسْرَى ۝ وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى ۝ وَكَذَّبَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْعُسْرَى [الليل:5-10]. فأنت يا عبدالله، عليك أن تعمل، ولن تخرج عن قدر الله  عليك أن تعمل، وتجتهد في طاعة الله، وتسأل ربك التوفيق، وعليك أن تحذر ما يضرك، وتسأل ربك الإعانة على ذلك، وأنت ميسر لما خلقت له، كل ميسر لما خلق له، نسأل الله للجميع الهداية، والتوفيق، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15538/هل-الانسان-في-هذه-الحياة-مسير-ام-مخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_822/nour_82210.mp3","categories":["القضاء والقدر"]},{"id":17698,"question":"عبارات كثيرة تتردد يقول السائل على ألسنة بعض الناس يقول من هذه الأقوال: شاء الحظ التعيس؟","title":"حكم قول: شاء الحظ التعيس","answer":"الجواب: ما يجوز يقول: شاء الحظ، ولا شاءت قدرة الله، ولا شاءت إرادة الله يقول: شاء الله سبحانه، شاء الله كذا، شاء ربي كذا، شاء الرحمن كذا، ولا يقول: شاء الحظ أو شاءت إرادة الله أو شاءت الظروف فهذا لا يجوز. نعم.\nالمقدم: جزاكم الله عنا وعن المسلمين خير الجزاء.","link":"https://binbaz.org.sa/fatwas/16649/حكم-قول-شاء-الحظ-التعيس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_776/nour_77609.mp3","categories":["القضاء والقدر"]},{"id":17710,"question":"هذا السائل الذي كتب هذا السؤال بأسلوبه الخاص فهمت منه بأنه يسأل ويقول: ما حكم الشرع في نظركم سماحة الشيخ فيمن يصاب بمصيبة تذهب بشعوره فيحصل منه التسخط من غير شعور، هل يؤاخذ على فعله مع أنه فاقد للعقل، وماذا يقول الإنسان عندما يصاب بمصيبة؟","title":"حكم تسخط فاقد الشعور عند المصيبة","answer":"الجواب: عليه الصبر والاحتساب ويقول: إنا لله وإنا إليه راجعون، قدر الله وما شاء فعل، اللهم آجرني في مصيبتي وأخلف لي خيرًا منها، كما بينه القرآن والسنة.\nأما الشيء الذي يقع منه وهو فاقد الشعور فالله جل وعلا يعفو عنه؛ لأن فاقد الشعور غير مكلف غير مؤاخذ كالمجنون وكالنائم وكالذي يصيبه ما يفقده الشعور من المصائب فلا حرج عليه حتى يعي، حتى يرجع إليه عقله قال ﷺ: رفع القلم عن ثلاثة: عن النائم حتى يستيقظ، وعن المجنون حتى يفيق، وعن الصغير حتى يبلغ والذي يفقد عقله مثل المجنون. نعم.\nالمقدم: أحسن الله إليكم وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16670/حكم-تسخط-فاقد-الشعور-عند-المصيبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_776/nour_77620.mp3","categories":["القضاء والقدر"]},{"id":18580,"question":"في الحديث سماحة الشيخ يقول: هل الدعاء يرد القدر؟ وكيف ذلك؟","title":"كيفية رد الدعاء للقدر","answer":"الجواب: نعم، الدعاء من أسباب رد القدر المعلق، والقدر يكون معلقًا، ويكون مبتوتًا، فإذا كان قدرًا معلقًا، قد قدر الله -جل وعلا- أن يهبه ولدًا إذا دعا ربه، فدعا ربه، واستجاب دعوته، هذا معلق بالدعاء، أو قدر الله له مالًا إذا دعا ربه في طلب ذلك المال، فإذا دعا ربه يسر الله له المال المعلق على الدعاء، أو طلب زوجة، طلب أن الله يزوجه فلانة، والله قد قدر له ذلك بهذا الطلب، قد علق القدر بهذا الطلب، أن فلان قدر الله في سابق علمه أنه يسأل ربه أن الله يزوجه فلانة بنت فلان، فإذا ألهمه الله الدعاء، ووفقه للدعاء؛ حصل المقدور المعلق. أما الأقدار المبتوتة التي ما هي معلقة على الناس هذه ما تتعلق بالدعاء، الموت المعلق في يوم معلوم دون دعاء إذا جاء موته المحدود مات دعا أو لم يدع، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17703/كيفية-رد-الدعاء-للقدر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_786/nour_78623.mp3","categories":["شروح الحديث","القضاء والقدر"]},{"id":18733,"question":"يقول هذا السائل: قرأت في كتاب إحياء علوم الدين للغزالي بأن الإنسان خلق ملزمًا بأعماله، سواءً كانت خيرًا أم شرًا وليس له الاختيار، واستدل بقوله تعالى: وَمَا تَشَاءُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ[الإنسان:30] واستدل بحديث النبي ﷺ الذي يقول: بأنه يكتب على كل إنسان، وهو في بطن أمه يكتب عمله شقي أو سعيد.وقرأت في بعض الكتب بأن الإنسان مخير في أعماله؛ بدليل قول الله تعالى: اعْمَلُوا مَا شِئْتُمْ[فصلت:40] فأنا الآن في حيرة، أفيدونا سماحة الشيخ في ذلك، فأنا أريد أن أعرف الجواب الصحيح؟","title":"تسيير العبد وتخييره","answer":"الجواب: أهل السنة والجماعة على أن العبد مخير ومسير لا يخرج عن قدر الله، والله أعطاه سبحانه العقل يتصرف، يأكل ويشرب، ويعمل ويأمر وينهى، يسافر ويقيم له أعمال كما قال تعالى: لِمَنْ شَاءَ مِنْكُمْ أَنْ يَسْتَقِيمَ ۝ وَمَا تَشَاءُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ[التكوير:28-29] جعل لهم مشيئة، قال: فَمَنْ شَاءَ ذَكَرَهُ[المدثر:55] قال: إِنَّ اللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ[البقرة:110]، إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ[النور:30]. فالعباد لهم أفعال: يأمرون وينهون، يسافرون ويقيمون، يصلون، ينامون، يعادون ويحبون، لهم أعمال، لكنهم لا يخرجون عن قدر الله، الله قدر الأشياء ، قدر الأشياء في سابق علمه، لا يخرجون عن قدر الله، لكن ليسوا مجبورين، بل هم مختارون لهم اختيار، ولهم عمل، ولهذا خاطبهم الله وأمرهم ونهاهم، وأخبر عن أعمالهم أنه خبير بأعمالهم: فَوَرَبِّكَ لَنَسْأَلَنَّهُمْ أَجْمَعِينَ ۝ عَمَّا كَانُوا يَعْمَلُونَ[الحجر:92-93]، إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ[النور:30] اعملوا ما شئتم فقد غفرت لكم لأهل بدر إلى غير ذلك. فالواجب على المؤمن أن يعرف هذا، فأهل السنة والجماعة يقولون: العبد مختار، له فعل وله اختيار، وله إرادة وله عمل، لكنه لا يخرج عن قدر الله، ثبت في الحديث الصحيح يقول النبي ﷺ: إن الله قدر مقادير الخلائق قبل أن يخلق السماوات والأرض، بخمسين ألف سنة، وكان عرشه على الماء وكذا قدر أعمال العبد في بطن أمه بعد مضي الشهر الرابع يكتب رزقه، وأجله، وعمله، وشقي أو سعيد، ما يخرج عن قدر الله، لكن له أعمال، وله تصرفات لا يخرج بها عن قدر الله، فهو يسافر، يصلي، يصوم، يزني، يسرق، يعق، يقطع الرحم، يطيع، يسافر، يصل فلانًا، يقطع فلانًا، يرحم فلانًا، ويؤذي فلانًا، يحسن إلى فلان، ويسيء إلى فلان، له أعمال طيبة وخبيثة، فهو مأجور على الطيبة، ومأزور على الخبيثة. والله يجازيه على أعماله الطيبة والخبيثة، على الطيبة بالجزاء الحسن، وعلى أعماله الرديئة بما يستحق، وقد يعفو إذا كان موحدًا، فهو سبحانه العفو، وهو -جل وعلا- العفو العظيم -جل وعلا-، يقول فيه النبي ﷺ: اللهم إنك عفو، تحب العفو، فاعف عني لما سئل «قيل: يا رسول الله، إذا كانت منازلنا في الجنة معلومة...» لما قال لهم: ما منكم من أحد إلا وقد علم مقعده من الجنة، ومقعده من النار قالوا: يا رسول الله، إذا كان هذا قد سبق في علم الله، ففيم العمل؟ كيف نعمل؟ قال: اعملوا فكل ميسر لما خلق له، أما أهل السعادة فييسرون لعمل أهل السعادة، وأما أهل الشقاوة فييسرون لعمل أهل الشقاوة ثم قرأ قوله تعالى: فَأَمَّا مَنْ أَعْطَى وَاتَّقَى ۝ وَصَدَّقَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْيُسْرَى ۝ وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى ۝ وَكَذَّبَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْعُسْرَى[الليل:5-10]»، ويقول -جل وعلا-: هُوَ الَّذِي يُسَيِّرُكُمْ فِي الْبَرِّ وَالْبَحْرِ[يونس:22]. فالعبد مسير بقدر الله، لكن له اختيار، وله مشيئة، وله عمل، يجازى على عمله الطيب، ويستحق العقاب على عمله الرديء إلا أن يعفو الله كما أخبر سبحانه في قوله تعالى: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ[النساء:48] قد يغفر عن بعض المعاصي لمن يشاء  إذا مات على التوحيد، وهكذا في الدنيا قد يعفو ويصفح عن بعض عباده فضلًا منه وإحسانًا ، وقد يعاقب على السيئات في الدنيا قبل الآخرة، نعم. المقدم: شكر الله لكم سماحة الشيخ، وبارك الله فيكم، وفي علمكم، ونفع بكم الإسلام والمسلمين.","link":"https://binbaz.org.sa/fatwas/17865/تسيير-العبد-وتخييره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_789/nour_78915.mp3","categories":["القضاء والقدر"]},{"id":19394,"question":"تفسير قول الحق تبارك وتعالى، أعوذ بالله من الشيطان الرجيم: إِنَّ اللَّهَ لا يُغَيِّرُ مَا بِقَوْمٍ حَتَّى يُغَيِّرُوا مَا بِأَنفُسِهِمْ [الرعد:11] تتساءل أختنا عن هذه الآية، فتقول: مع أن الله هو الذي خلق الأنفس وهو الذي يتحكم بتغييرها، فكيف يستطيع القوم أن يغيروا ما بأنفسهم ويغيروا ما كتب عليهم، أرجو من سماحة الشيخ عبد العزيز أن يتفضل بالشرح الوافي حول هذا الموضوع؟ جزاكم الله خيرًا.","title":"القضاء والقدر ووجوب الأخذ بالأسباب","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفالله  هو مدبر الأمور وهو مصرف العباد كما يشاء  وله الحكمة البالغة والحجة الدامغة، وهو سبحانه قد شرع لعباده الأسباب التي تقربهم منه وتسبب رحمته وإحسانه إليهم، ونهاهم عن الأسباب التي تسبب غضبه عليهم وبعدهم منه وحلول العقوبات بهم، ومع ذلك هم بهذا لا يخرجون عن قدره، هم بفعل الأسباب التي شرعها لهم والتي نهاهم عنها هم لا يخرجون بهذا عن قدره سبحانه، فالله أعطاهم عقولًا وأعطاهم أدوات وأعطاهم أسبابًا يستطيعون بها أن يتحكموا فيما يريدون من جلب خير أو دفع شر وهم بهذا لا يخرجون عن مشيئته، كما قال : لِمَنْ شَاءَ مِنْكُمْ أَنْ يَسْتَقِيمَ ۝ وَمَا تَشَاءُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ رَبُّ الْعَالَمِينَ [التكوير:28-29]. وقد سئل النبي ﷺ عن هذا، قالوا له: يا رسول الله! إذا كان ما نفعله قد كتب علينا وفرغ منه ففيم العمل؟ قال عليه الصلاة والسلام: اعملوا فكل ميسر لما خلق له، أما أهل السعادة فييسرون لعمل أهل السعادة، وأما أهل الشقاوة فييسرون لعمل أهل الشقاوة، ثم تلا عليه الصلاة والسلام قوله تعالى: فَأَمَّا مَنْ أَعْطَى وَاتَّقَى ۝ وَصَدَّقَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْيُسْرَى ۝ وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى ۝ وَكَذَّبَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْعُسْرَى [الليل:5-10]، فهكذا قوله جل وعلا: إِنَّ اللَّهَ لا يُغَيِّرُ مَا بِقَوْمٍ حَتَّى يُغَيِّرُوا مَا بِأَنفُسِهِمْ وَإِذَا أَرَادَ اللَّهُ بِقَوْمٍ سُوءًا فَلا مَرَدَّ لَهُ وَمَا لَهُمْ مِنْ دُونِهِ مِنْ وَالٍ [الرعد:11]. فأمره نافذ  لكنه جل وعلا يغير ما بالناس إذا غيروا، فإذا كانوا على طاعة واستقامة ثم غيروا إلى المعاصي غير الله حالهم من الطمأنينة والسعادة والخصب والرخاء إلى ضد ذلك بسبب معاصيهم وذنوبهم، وقد يملي لهم سبحانه، وقد يتركهم على حالهم استدراجًا ثم يأخذهم على غرة، ولا حول ولا قوة إلا بالله، كما قال : وَلا تَحْسَبَنَّ اللَّهَ غَافِلًا عَمَّا يَعْمَلُ الظَّالِمُونَ إِنَّمَا يُؤَخِّرُهُمْ لِيَوْمٍ تَشْخَصُ فِيهِ الأَبْصَارُ [إبراهيم:42]، وقال سبحانه: فَلَمَّا نَسُوا مَا ذُكِّرُوا بِهِ فَتَحْنَا عَلَيْهِمْ أَبْوَابَ كُلِّ شَيْءٍ حَتَّى إِذَا فَرِحُوا بِمَا أُوتُوا أَخَذْنَاهُمْ بَغْتَةً فَإِذَا هُمْ مُبْلِسُونَ [الأنعام:44]. فالواجب الحذر، فعلى المؤمن أن يتقي الله، وأن يلزم الحق، وأن يستقيم عليه، وأن لا يحيد عنه إلى الباطل؛ فإنه متى حاد عنه إلى الباطل فقد تعرض لغضب الله أن يغير قلبه وأن يغير ما به من نعمة إلى جدب وقحط وفقر وحاجة، وهكذا بعد الصحة إلى مرض وهكذا بعد الأمن إلى خوف إلى غير ذلك بأسباب الذنوب والمعاصي. وهكذا العكس إذا كانوا في معاصي وشرور وانحراف ثم توجهوا إلى الحق وتابوا إلى الله ورجعوا إليه واستقاموا على دينه، فإن الله يغير ما بهم سبحانه من الخوف والفقر والاختلاف والتشاحن إلى أمن وعافية واستقامة وإلى رخاء وإلى محبة وإلى تعاون وإلى تقارب فضلًا منه وإحسانًا  ومن هذا قوله تعالى: ذَلِكَ بِأَنَّ اللَّهَ لَمْ يَكُ مُغَيِّرًا نِعْمَةً أَنْعَمَهَا عَلَى قَوْمٍ حَتَّى يُغَيِّرُوا مَا بِأَنفُسِهِمْ [الأنفال:53] . فالعبد عنده أسباب، عنده عمل، عنده إرادة، عنده مشيئة، ولكنه بذلك لا يخرج عن قدر الله  فالواجب عليه أن يستعمل ما استطاع من طاعة الله ورسوله، وأن يستقيم على ما أمره الله به، وأن يحذر ما نهى الله عنه، وأن يسأل ربه العون والتوفيق، والله  هو المتفضل وهو الموفق وهو الهادي جل وعلا، وله الفضل وله النعمة وله الإحسان  في يده توفيق العباد، وبيده هدايتهم، وبيده إضلالهم، يهدي من يشاء، ويضل من يشاء . المقدم: جزاكم الله خيرًا ونفع بعلمكم، لعل الموضوع يحتاج إلى إعادة ملخصة شيخ عبد العزيز ، فالموضوع له. الشيخ: الحاصل أن العبد له أسباب، العبد عنده أسباب والله أعطاه أدوات وعقلًا يعرف بها الضار والنافع والخير والشر، فإذا استعمل عقله وأسبابه في الخير جازاه الله على ذلك بالخير العظيم، وأدر عليه نعمه، وجعله في نعمة وعافية بعدما كان في سوء وشر بمعاصيه الأولى، فإذا تاب إلى الله وأناب واستقام فالله جل وعلا من جوده وكرمه يغير حاله السيئة إلى حالة حسنة، وهكذا العكس إذا كان العبد على طاعة واستقامة وهدى ثم انحرف وحاد عن الطريق وتابع الهوى والشيطان، فالله سبحانه قد يعاجله بالعقوبة، وقد يغير عليه وقد يمهله  فينبغي أن يحذر وينبغي أن لا يغتر بإمهال الله إذا أمهله . المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18616/القضاء-والقدر-ووجوب-الاخذ-بالاسباب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_935/nour_93501.mp3","categories":["القضاء والقدر"]},{"id":19396,"question":"شيخ عبد العزيز، الكثير يخوضون في موضوع القضاء والقدر، لعل لكم توجيه؟","title":"التحذير من الخوض في باب القدر","answer":"الجواب: هذا باب خاضه الأولون أيضًا وغلط فيه من غلط، والواجب على كل مؤمن وعلى كل مؤمنة التسليم لله، والإيمان بقدره سبحانه، والحرص على الأخذ بالأسباب النافعة الطيبة، والبعد عن الأسباب الضارة، كما علم الله عباده وكما جعل لهم قدرة على ذلك بما أعطاهم من العقول والأدوات التي يستعينون بها على طاعته وترك معصيته . المقدم: إذًا لا تنصحون بالخوض في هذا الباب؟ الشيخ: لا ننصح لا، بل ينبغي عدم الخوض في هذا الباب، والإيمان بأن الله قدر الأشياء وعلمها وأحصاها، وأن ما شاء الله كان وما لم يشأ لم يكن، وأنه الخلاق العظيم القادر على كل شيء. وأن جميع الموجودات كلها بخلقه وتكوينه  وأن الله سبحانه أعطى العبد عقلًا تصرفًا وأسبابًا وقدرة على الخير والشر، كما يأكل ويشرب ويلبس وينكح ويسافر ويقيم وينام ويقوم إلى غير ذلك كذلك يطيع ويعصي. المقدم: هل هناك من محاذير شيخ عبد العزيز تخشونها على الخائضين في القضاء والقدر؟ الشيخ: نخشى عليهم أن يحتجوا بالقدر أو ينكروه؛ لأن قومًا خاضوا فيه فأنكروه كالـقدرية النفاة وقالوا: لا قدر، وزعموا أنهم يخلقون أفعالهم، وأن الله ما تفضل عليهم بالطاعة ولا قدر عليهم المعصية، وقوم قالوا: بل تفضل الله بالطاعة، ولكن ما قدر المعصية، فوقعوا في الباطل أيضًا. وقوم خاضوا في القدر فقالوا: إنا مجبورون، وقالوا: إنهم ما عليهم شيء عصوا أو أطاعوا لا شيء عليهم؛ لأنهم مجبورون ولا قدرة لهم، فضلوا وأضلوا، نسأل الله العافية. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18617/التحذير-من-الخوض-في-باب-القدر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_935/nour_93502.mp3","categories":["القضاء والقدر"]}]
